window.PREPA = {"meta":{"built":"2026-11-09T14:44:32.397Z"},"modules":[{"id":"m01-rendezvous","order":1,"title":"Le rendez-vous de 18 h","subtitle":"Qui est en face, et ce que cet entretien évalue","format":"video","workMinutes":7,"why":"Savoir qui est Frédéric Bertrais et ce que mc2i évalue à ce stade te dit où mettre tes deux heures.","voice":"Sulafat","scenes":[{"layout":"title","kicker":"Ce soir, 18 heures","heading":"Qui est en face, et ce qui se joue","sub":"Frédéric Bertrais, Directeur et Associé chez mc2i"},{"layout":"flow","kicker":"Le parcours","heading":"Quinze ans chez mc2i, un ancrage finance","items":[{"t":"Cetelem, BNP Paribas","d":"Analyst, puis business analyst"},{"t":"Consultant mc2i","d":"Senior Consultant dès juin 2011"},{"t":"Londres","d":"Project Manager, Total, 2014-2018"},{"t":"Senior Manager","d":"Caisse des Dépôts, 2019-2023"},{"t":"Directeur & Associé","d":"Depuis décembre 2023"}]},{"layout":"cards","kicker":"Le périmètre actuel","heading":"Risque, contrôles, résilience","items":[{"t":"Notation crédit","d":"Outil clients corporate : Product Owner, agilité"},{"t":"Risque opérationnel","d":"Suivi des contrôles et plans d'actions (RCSA / LoD2)"},{"t":"Résilience","d":"Mise en place en contexte bancaire (DORA)"},{"t":"Management","d":"Managers et Senior Managers : commercial et qualité"}]},{"layout":"cards","kicker":"Ce que ça te dit","heading":"Un praticien du produit et de la recette","items":[{"t":"Scrum","d":"PSPO I, PSM II, PRINCE2 Foundation"},{"t":"Caisse des Dépôts","d":"5 équipes agiles ; prêts aux collectivités"},{"t":"Recette","d":"Tribune de 2012 sur les outils de recette"},{"t":"Conséquence","d":"Exemples précis, vocabulaire juste, aucun bluff"}]},{"layout":"flow","kicker":"Le processus officiel","heading":"Tu es au tour 2, peut-être au tour 3","items":[{"t":"Préqualification RH","d":"Par téléphone"},{"t":"Entretien 1","d":"Recruteur opérationnel, le 15/10"},{"t":"Entretien 2","d":"Senior Manager, Directeur ou Partner"},{"t":"Entretien 3","d":"Membre de la Direction"}]},{"layout":"bullets","kicker":"Page officielle mc2i","heading":"Ce que l'étape 2 évalue","items":["Tes expériences, approfondies une par une","Compétences comportementales et techniques","Ton potentiel","Les missions proposées chez mc2i","Tes prétentions salariales"]},{"layout":"compare","kicker":"Ce que ça change","heading":"Aucune étude de cas : la matière, c'est toi","left":{"t":"Inutile ce soir","items":["Cas à résoudre","Exercices de chiffrage","Articles de loi récités"]},"right":{"t":"À préparer","items":["Ton rôle exact, ce que tu as produit","Tes limites, dites avant qu'on les trouve","Si on te le demande : 44-46 k€ brut fixe"]}},{"layout":"cards","kicker":"Annoncé le 15 octobre","heading":"Les cinq thèmes de Marion Auger","items":[{"t":"Missions","d":"Lesquelles tu veux, concrètement"},{"t":"Secteur","d":"Ce que tu en connais"},{"t":"Projection","d":"Dans cinq ans : quel poste, quel secteur"},{"t":"Sous-secteur","d":"Banque, assurance, crédit : un choix précis"},{"t":"Ton rôle","d":"Ce que tu as produit exactement"}]},{"layout":"quote","kicker":"Le fil rouge","heading":"La motivation, testée en creusant","quote":"« la motivation qui est saine et qui vous permettra ensuite de grandir dans ces environnements »","author":"Marion Auger, entretien du 15 octobre"}],"takeaways":["Frédéric Bertrais vient du terrain : business analysis, recette, Product Owner, Scrum. Les exemples vagues ne passeront pas.","Son périmètre affiché : notation du risque de crédit corporate, suivi des contrôles RCSA, résilience DORA.","Ce soir : expériences approfondies, comportement, technique, potentiel, missions, salaire. Aucune étude de cas.","Tour 2 ou tour 3, aucune source ne tranche : prépare le 2 et garde une projection à long terme nette.","Trois réponses à rendre nettes : sous-secteur, mission voulue, projection à cinq ans."],"quiz":[{"q":"Marion Auger t'a dit « il n'y a pas de choses à préparer ». Que faut-il en retenir ?","choices":["L'entretien est informel, une relecture du CV suffit.","Il n'y a rien de formel à rendre, mais tu dois te renseigner et détailler ton rôle et tes productions.","Il faut surtout préparer une étude de cas, car le Directeur évalue la technique."],"answer":1,"why":"La phrase continue : se renseigner via podcasts, LinkedIn et site, puis « expliquer plus concrètement quel était vos rôles, ce que vous avez fait, ce que vous avez produit »."},{"q":"Frédéric Bertrais est Directeur et Associé. À quel tour du processus es-tu ce soir ?","choices":["Au tour 3, puisqu'un Directeur fait forcément partie de la Direction.","Au tour 2, la page officielle le dit explicitement pour ce rendez-vous.","Tour 2 ou tour 3 : aucune source ne tranche, tu prépares le 2 et une projection à long terme."],"answer":2,"why":"La page cite « Senior Manager, Directeur ou Partner » au tour 2 et un « membre de la Direction » au tour 3. Le titre de Frédéric Bertrais peut correspondre aux deux."},{"q":"Quarante minutes sont passées et personne n'a parlé de rémunération. Que fais-tu ?","choices":["Tu annonces 44-46 k€ pour montrer que tu connais ta valeur.","Tu ne l'ouvres pas en premier. Si la question vient, tu réponds 44-46 k€ brut fixe.","Tu demandes quelle est la grille d'entrée chez mc2i avant de donner un chiffre."],"answer":1,"why":"Le sujet est prévu à cette étape, mais c'est à ton interlocuteur de l'ouvrir. Ta réponse tient en une fourchette, sans justification à rallonge."}],"drill":{"prompt":"On te demande : « Vous savez sur quels sujets je travaille ? » Réponds à voix haute, sans bluffer, et termine par une question.","seconds":60,"model":"J'ai vu que vous interveniez sur des outils risque en mode produit : la notation du risque de crédit pour les clients corporate, le suivi des contrôles RCSA, et la résilience opérationnelle avec DORA. Je ne connais pas ce métier. Ce qui me parle, c'est la question de la donnée fiable pour des utilisateurs exigeants, que j'ai rencontrée à plus petite échelle sur mon reporting mensuel chez Orange. Sur un outil comme le suivi des contrôles RCSA, qu'est-ce qui rend le rôle de Product Owner difficile par rapport à un produit grand public ?"},"video":"media/m01-rendezvous.mp4#t=0.6","mediaMinutes":4.2},{"id":"m02-amoa","order":2,"title":"Le métier d'AMOA","subtitle":"Les acteurs, les étapes, les livrables, le quotidien d'un junior","format":"video","workMinutes":10,"why":"Le poste s'intitule AMOA : à 18h, tu dois parler de ce métier avec ses mots et ses documents, à partir de ce que tu as déjà fait.","voice":"Sulafat","scenes":[{"layout":"title","kicker":"Module 2","heading":"Le métier d'AMOA en dix minutes","sub":"Ce qu'un Directeur attend d'un junior qui en parle"},{"layout":"cards","kicker":"Les trois acteurs","heading":"MOA, MOE, et le trait d'union","items":[{"t":"MOA","d":"Le client, le métier : porte le besoin, décide, valide"},{"t":"AMOA","d":"Aide la MOA à exprimer, formaliser et suivre ses besoins"},{"t":"MOE","d":"Conçoit et réalise la solution technique"}]},{"layout":"flow","kicker":"Cycle de vie","heading":"Du besoin à la vie de l'outil","items":[{"t":"Cadrage","d":"Objectif, périmètre, calendrier"},{"t":"Spécifications","d":"Règles, données, interfaces"},{"t":"Réalisation","d":"La MOE construit, tu clarifies"},{"t":"Recette","d":"On vérifie par rapport au besoin"},{"t":"MEP et run","d":"Livraison, puis vie de l'outil"}]},{"layout":"compare","kicker":"Deux méthodes","heading":"Cycle en V contre agile","left":{"t":"Cycle en V","items":["Phases successives","Besoin figé tôt, validé à la fin","Chaque test répond à une conception","Recette en fin de parcours"]},"right":{"t":"Agile","items":["Itérations courtes","Backlog priorisé en continu","User stories, critères d'acceptation","Produit montré régulièrement"]}},{"layout":"cards","kicker":"Les rôles en agile","heading":"Product Owner et business analyst","items":[{"t":"Product Owner","d":"Porte la valeur du produit et priorise le backlog"},{"t":"Business analyst","d":"Exigences, flux, données, souvent en soutien du PO"},{"t":"User story","d":"En tant que… je veux… afin de…, avec critères vérifiables"},{"t":"Référence mc2i","d":"AMOA en équipes Scrum, organisation SAFe, banque 100 % mobile"}]},{"layout":"cards","kicker":"Ce que tu produis","heading":"Six livrables à citer avec leur usage","items":[{"t":"Cahier des charges","d":"Ce que le projet doit atteindre"},{"t":"Spécifications","d":"Écrans, règles de gestion, données, interfaces"},{"t":"Plan de recette","d":"Stratégie, périmètre, calendrier"},{"t":"Cahier de tests","d":"Cas, données, résultat attendu"},{"t":"Suivi des anomalies","d":"Chaque défaut, de l'ouverture à la correction"},{"t":"PV et comptes rendus","d":"Validation actée, décisions tracées"}]},{"layout":"compare","kicker":"La recette","heading":"Deux recettes, deux questions différentes","left":{"t":"Recette d'usine (MOE)","items":["Ce qui est construit fonctionne-t-il ?","Faite par l'équipe technique","Avant la livraison à la MOA"]},"right":{"t":"Recette MOA","items":["Cela répond-il au besoin ?","Cas de test métier, cahier de recette","Se conclut par un PV de recette"]}},{"layout":"flow","kicker":"Livrer et faire adopter","heading":"MEP et conduite du changement","items":[{"t":"Impacts","d":"Qui est touché, qu'est-ce qui change"},{"t":"Communication","d":"Prévenir, expliquer, rassurer"},{"t":"Formation","d":"Guides, sessions, relais métier"},{"t":"MEP","d":"Plan, migration, retour arrière"},{"t":"Suivi","d":"Premiers jours, usage, anomalies"}]},{"layout":"flow","kicker":"Journée type, illustration","heading":"Une journée de junior en mission","items":[{"t":"Point d'équipe","d":"Priorités et blocages"},{"t":"Atelier métier","d":"Clarifier une règle de gestion"},{"t":"Rédaction","d":"Spécification ou user story"},{"t":"Tests","d":"Cas joués, anomalies ouvertes"},{"t":"Compte rendu","d":"Décisions, actions, suivi à jour"}]},{"layout":"bullets","kicker":"Ce qui fait la différence","heading":"Les réflexes d'un bon AMOA","items":["Demander pourquoi avant de noter quoi","Vérifier que tout le monde parle de la même chose","Écrire pour un développeur et pour un métier","Annoncer un risque tôt, avec une proposition","Dire « je ne sais pas », puis revenir avec la réponse"]},{"layout":"quote","kicker":"Ta phrase","heading":"Ce que tu peux dire à 18h","quote":"Avant d'afficher un indicateur, je vérifie que tout le monde parle de la même chose.","author":"Ta phrase de liaison"}],"takeaways":["L'AMOA prépare et conseille, la décision reste à la MOA.","Chaque phase de test du cycle en V répond à une phase de conception, et la posture fonctionnelle reste la même en agile.","La recette d'usine appartient à la MOE, la recette métier se joue à partir du besoin et se conclut par un PV.","Cite les livrables avec leur usage : cela montre que tu sais à quoi ils servent.","Ton meilleur exemple AMOA : le rapprochement des définitions dans le reporting Orange."],"quiz":[{"q":"La MOE annonce que sa recette d'usine est passée à 100 %. Le chef de projet propose de sauter la recette métier pour tenir la date. Que réponds-tu ?","choices":["D'accord : les tests sont déjà faits, recommencer serait du temps perdu","Les deux recettes répondent à des questions différentes : je propose de réduire le périmètre aux cas métier critiques et de laisser la MOA décider","Je refuse et je préviens immédiatement la direction du client"],"answer":1,"why":"La recette d'usine vérifie que c'est construit correctement, la recette MOA vérifie que cela répond au besoin. L'AMOA propose un arbitrage, la MOA décide."},{"q":"En mission agile, tu détailles les flux et les données en soutien d'un Product Owner qui priorise le backlog. Quel rôle occupes-tu ?","choices":["Business analyst, un rôle qui se recouvre souvent avec celui d'AMOA","Scrum Master, puisque tu aides l'équipe","Aucun : l'agile supprime tout travail fonctionnel en dehors du Product Owner"],"answer":0,"why":"Le BA produit exigences, flux et modèles de données, souvent en soutien du PO. La posture de traducteur fonctionnel survit très bien à l'agile. Attention : le rapprochement AMOA et BA est une lecture courante, sans définition officielle."},{"q":"« Vous avez déjà fait de l'AMOA ? » Quelle réponse tient face à un Directeur qui creuse ?","choices":["« Oui, j'ai mené de A à Z un projet AMOA chez Orange. »","« Non, je pars de zéro sur ce métier. »","« En appui du Product Owner, mon tuteur, j'ai recueilli les besoins et rédigé les spécifications. La recette à l'échelle d'un SI bancaire, je ne l'ai pas encore pratiquée. »"],"answer":2,"why":"Le « A à Z » ne résiste pas à la première relance, et « zéro » jette tes preuves. Tu dis ce que tu as fait, puis ce qu'il te reste à apprendre."}],"drill":{"prompt":"À voix haute : « Qu'est-ce que l'AMOA, pour vous, et qu'en avez-vous déjà pratiqué ? »","seconds":60,"model":"L'AMOA fait le lien entre le métier, qui porte le besoin, et les équipes techniques, qui réalisent. Elle aide à exprimer ce besoin, le formalise en spécifications, avec les règles de gestion et les données, puis suit la réalisation, prépare la recette et accompagne le déploiement. J'en ai pratiqué une partie chez Orange, en appui du Product Owner, mon tuteur. Trois pôles avaient des besoins différents : l'équipe App Center, les pays et la technique. J'ai recueilli leurs besoins, puis rédigé un carnet de spécifications avec le rôle de chacun, ce qu'il voulait et pourquoi. Le reporting mensuel, envoyé à 130 destinataires, a été refondu en dashboard self-service. Ce qu'il me reste à acquérir, c'est la culture bancaire et la recette sur un système d'information de grande taille."},"video":"media/m02-amoa.mp4#t=0.6","mediaMinutes":5.2},{"id":"m03-secteur","order":3,"title":"Banque et assurance : la carte","subtitle":"Les offres de mc2i, les acteurs, les enjeux, le vocabulaire, l'actualité","format":"video","workMinutes":9,"why":"Marion Auger a annoncé des questions sur tes connaissances sectorielles et ton choix de sous-secteur : il te faut une carte claire et quelques faits datés.","voice":"Sulafat","scenes":[{"layout":"title","kicker":"Module 3","heading":"Banque et assurance : la carte","sub":"Savoir où sont les choses, et ce qui se passe cette semaine"},{"layout":"cards","kicker":"L'offre banque de mc2i","heading":"Six offres à savoir citer","items":[{"t":"Risques, réglementaire","d":"Bâle 3, CRR/CRD, DORA, MIFID, risques opérationnels, crédit"},{"t":"Digital et paiements","d":"Instant Payment, enrôlement, souscription, CRM, vie du compte"},{"t":"Crédits","d":"SI Crédit front-to-back"},{"t":"Financement, invest.","d":"Banque de financement et d'investissement"},{"t":"Finance verte","d":"Offre affichée en propre par mc2i"},{"t":"Transverses, innovation","d":"Sujets communs à plusieurs métiers"}]},{"layout":"flow","kicker":"Le risque, en clair","heading":"Les trois lignes de défense","items":[{"t":"LoD1 : métiers","d":"Propriétaires des risques et contrôles"},{"t":"LoD2 : contrôle","d":"Risques et conformité : cadre, challenge"},{"t":"LoD3 : audit","d":"Vérification indépendante de l'ensemble"}]},{"layout":"stats","kicker":"Ton terrain","heading":"Banque digitale et moyens de paiement","items":[{"v":"8,5 %","l":"transformation, contre 6,5 % (réf. mc2i)"},{"v":"4,5/5","l":"Apple Store, contre 3,1 (réf. mc2i)"},{"v":"2025","l":"virement instantané, zone euro"},{"v":"~56 M","l":"utilisateurs Wero (chiffres variables)"}]},{"layout":"flow","kicker":"Crédit et financement","heading":"Le crédit, de la demande à la gestion","items":[{"t":"Demande","d":"Le client ou l'entreprise sollicite"},{"t":"Instruction","d":"Analyse du dossier et du risque"},{"t":"Décision","d":"Accord, conditions, garanties"},{"t":"Mise en place","d":"Contrat, déblocage des fonds"},{"t":"Gestion","d":"Remboursements, réaménagements"}]},{"layout":"cards","kicker":"L'offre assurance de mc2i","heading":"L'assurance, en six entrées","items":[{"t":"Systèmes cœur","d":"Guidewire : contrats, souscription, sinistres, facturation"},{"t":"Data et IA","d":"IA générative et agentique"},{"t":"Réglementaire","d":"DORA, IA Act, CSRD, eIDAS 2.0, FIDA"},{"t":"Expérience client","d":"Offre mc2i. Exemple : résiliation, loi Lemoine"},{"t":"Nouveaux risques","d":"Offre affichée par mc2i"},{"t":"Change","d":"Accompagner la transformation des équipes"}]},{"layout":"compare","kicker":"Qui est qui","heading":"Les établissements et leurs superviseurs","left":{"t":"Établissements","items":["BNP Paribas, Société Générale","Crédit Agricole, BPCE","Banques en ligne, en hausse","Aéma : Macif, Aésio"]},"right":{"t":"Superviseurs","items":["ACPR et AMF en France","EBA : banque","EIOPA : assurance, ESMA : marchés","AMLA : anti-blanchiment, dès 2028"]}},{"layout":"bullets","kicker":"Les enjeux","heading":"Quatre tensions qui traversent le secteur","items":["Digitaliser dans un marché très réglementé","Application fluide et humain aux moments clés","IA déployée, règles haut risque sur le scoring fin 2027","Prestataires maîtrisés : 19 tiers critiques sous DORA"]},{"layout":"cards","kicker":"Vocabulaire indispensable","heading":"Six mots à comprendre sans traduction","items":[{"t":"Enrôlement","d":"Entrée en relation du client sur l'application"},{"t":"Vie du compte","d":"Tout ce qui suit l'ouverture"},{"t":"VoP","d":"Vérification de concordance entre nom et IBAN"},{"t":"Monétique","d":"Le monde de la carte de paiement"},{"t":"PD","d":"Probabilité de défaut d'un emprunteur"},{"t":"RCSA","d":"Auto-évaluation des risques et contrôles par les métiers"}]},{"layout":"flow","kicker":"L'actualité","heading":"Les dates qui comptent cet hiver","items":[{"t":"20 nov. 2026","d":"CCD2 : crédit conso, paiement fractionné"},{"t":"14 déc. (indicatif)","d":"PSR/DSP3 en plénière"},{"t":"Fin 2026","d":"Portefeuille d'identité européen"},{"t":"1er janv. 2027","d":"FRTB, avec ajustement de trois ans"},{"t":"30 janv. 2027","d":"Solvabilité II révisée"}]},{"layout":"stats","kicker":"Baromètre mc2i 2026","heading":"Quatre chiffres de leur propre étude","items":[{"v":"62 %","l":"centralisés dans un seul établissement"},{"v":"90 %","l":"de satisfaction sur le conseiller"},{"v":"44 %","l":"fidèles à une banque IA, sous conditions"},{"v":"55 %","l":"exigent un hébergement européen"}]},{"layout":"quote","kicker":"Ton angle","heading":"La phrase à reprendre","quote":"Une application mobile parfaite ne suffit plus à différencier une marque.","author":"Baromètre de la Banque de demain 2026, mc2i"}],"takeaways":["Six offres banque chez mc2i : tu te places sur banque digitale et moyens de paiement.","Le terrain de Frédéric Bertrais, c'est le risque : comprends les mots, ne prétends pas les pratiquer.","Trois faits datés à placer : CCD2 le 20 novembre, FIDA bloquée avec un retrait évoqué, Solvabilité II révisée le 30 janvier 2027.","Le baromètre 2026 te donne ton angle : l'application est un prérequis, l'enjeu passe au parcours et à la relation client.","Pour une référence mobile, cite la banque 100 % mobile de mc2i, jamais Orange Bank."],"quiz":[{"q":"Tu veux illustrer la banque mobile avec une référence publiée par mc2i. Laquelle choisis-tu ?","choices":["Orange Bank, puisque tu viens d'Orange","La banque française 100 % mobile : AMOA en équipes Scrum, transformation à 8,5 % contre 6,5 %","Hello bank!, qui a repris les clients français d'Orange Bank"],"answer":1,"why":"L'activité d'Orange Bank s'est arrêtée en 2024, et ton passage chez Orange Innovation n'a aucun lien avec elle. Aucune source ne fait de Hello bank! une référence mc2i."},{"q":"« Vos 44 % du baromètre, ça veut dire que les Français sont prêts à se passer de conseillers ? » Quelle réponse est juste ?","choices":["Oui : 44 % préfèrent désormais une IA à un conseiller","Non : ces 44 % resteraient fidèles sous réserve de tarifs en baisse et de performances en hausse, et 90 % sont satisfaits de leur conseiller","Non : seuls 44 % utilisent encore une agence"],"answer":1,"why":"Le chiffre porte sur la fidélité sous conditions. La fréquentation des agences, c'est 57 %. Une lecture rapide te ferait dire le contraire de l'étude, et c'est leur étude."},{"q":"FIDA pourrait être retirée. Qu'en déduis-tu pour l'open banking ?","choices":["L'extension à l'open finance est bloquée, l'open banking continue de reposer sur DSP2 et sera repris par la PSR","L'open banking s'arrête avec FIDA","FIDA est déjà en application, le retrait ne change rien avant 2028"],"answer":0,"why":"FIDA est l'extension de l'open banking à d'autres données financières. Le socle DSP2 reste. Dis « un retrait est évoqué » : l'information vient d'un projet de programme de travail."}],"drill":{"prompt":"À voix haute : « Comment voyez-vous le secteur, et où vous placez-vous ? »","seconds":60,"model":"Côté banque, votre offre couvre les risques et le réglementaire, la banque digitale et les moyens de paiement, les crédits, le financement et l'investissement, la finance verte et des sujets transverses. Côté assurance, les systèmes cœur comme Guidewire, la data et l'IA, le réglementaire et l'expérience client. Je me place sur la banque digitale et les paiements : application, enrôlement, souscription, CRM, vie du compte. Votre baromètre 2026 montre que l'application est devenue un prérequis : l'enjeu se déplace vers le parcours et la relation client. Chez Orange, en appui du Product Owner, mon tuteur, j'ai recueilli des besoins et écrit des spécifications pour un produit mobile. Je n'ai pas encore la culture bancaire, et je viens la construire chez vous. J'exprime une préférence, et je sais que vous recrutez sur profil : sur un outil de risque, je m'investirais de la même façon."},"video":"media/m03-secteur.mp4#t=0.6","mediaMinutes":5.2},{"id":"m04-terrain","order":4,"title":"Ton terrain","subtitle":"Banque digitale et paiements : le pivot en continuité","format":"video","workMinutes":10,"why":"Marion Auger a annoncé la question du sous-secteur : ce soir, tu arrives avec un choix, des raisons et des exemples.","voice":"Sulafat","scenes":[{"layout":"title","kicker":"Ton choix","heading":"Banque digitale et moyens de paiement","sub":"Le sous-secteur où ton parcours se lit sans traduction"},{"layout":"cards","kicker":"Ce que ça recouvre","heading":"Une offre publique de mc2i","items":[{"t":"Enrôlement","d":"Devenir client depuis son téléphone"},{"t":"Souscription","d":"Ouvrir un produit dans le parcours"},{"t":"Vie du compte","d":"Opérations courantes et options"},{"t":"Paiements","d":"Virement instantané, monétique"},{"t":"CRM","d":"Segmenter, déclencher la bonne action"}]},{"layout":"bullets","kicker":"Pourquoi celui-là","heading":"Trois raisons, à dire dans cet ordre","items":["Tes preuves mobiles passent sans traduction","mc2i publie une référence sur ce terrain","Actualité : instantané, Wero, baromètre 2026"]},{"layout":"stats","kicker":"La référence mc2i","heading":"Une banque française 100 % mobile","items":[{"v":"8,5 %","l":"taux de transformation, contre 6,5 %"},{"v":"4,5/5","l":"Apple Store, contre 3,1"},{"v":"Scrum","l":"consultants AMOA en équipes agiles"}]},{"layout":"quote","kicker":"Baromètre mc2i 2026","heading":"Ton argument, écrit par mc2i","quote":"« une application mobile parfaite ne suffit plus à différencier une marque, elle est simplement devenue un prérequis invisible »","author":"Baromètre de la Banque de demain 2026, mc2i"},{"layout":"cards","kicker":"L'actualité utile","heading":"Trois dates, et Wero sans date","items":[{"t":"Janvier 2025","d":"Instantané au tarif du virement classique, zone euro"},{"t":"Octobre 2025","d":"Vérification du bénéficiaire : nom et IBAN"},{"t":"20 novembre 2026","d":"Paiement fractionné : crédit réglementé (CCD2)"},{"t":"Wero","d":"Extension au paiement en ligne, les dates divergent"}]},{"layout":"flow","kicker":"Le récit","heading":"Le pivot en trente secondes","items":[{"t":"Orange, App Center","d":"Chef de produit junior, en appui du PO"},{"t":"Besoins et specs","d":"Pays, métier, résultats suivis"},{"t":"Même support","d":"Application, enrôlement, relation client"},{"t":"Ce qui manque","d":"Culture bancaire et réglementaire"},{"t":"mc2i","d":"La construire à partir de ton métier"}]},{"layout":"cards","kicker":"Les ponts","heading":"Ce que tu as fait, ce dont la banque a besoin","items":[{"t":"Besoins et parcours","d":"Spécifications mobile : enrôlement et souscription"},{"t":"Données et définitions","d":"Reporting, 130 destinataires : indicateurs de pilotage"},{"t":"Relation client","d":"Nexus Ops : CRM, vie du compte, consentement"}]},{"layout":"compare","kicker":"La limite à assumer","heading":"Dis-le avant qu'on te le fasse remarquer","left":{"t":"Ce qui se transfère","items":["Recueil des besoins","Spécifications","Parcours mobile","Données fiables"]},"right":{"t":"Ce qui reste à acquérir","items":["Culture bancaire","Réglementation en pratique","Vocabulaire risque et crédit"]}},{"layout":"quote","kicker":"Le lien avec ton interlocuteur","heading":"Honnête sur la matière, précis sur le produit","quote":"Je ne connais pas ce métier. Ce qui me parle, c'est la donnée fiable pour des utilisateurs exigeants.","author":"Ton amorce, si le risque arrive"},{"layout":"bullets","kicker":"Si on t'emmène ailleurs","heading":"Une préférence, et de l'ouverture","items":["Recrutement sur profil : tu ne choisis pas ta mission","« J'irai volontiers. La matière, je l'apprendrai. »","Banque digitale : là où tu seras utile vite","DORA : le principe connu, aucune pratique"]},{"layout":"title","kicker":"À savoir par cœur","heading":"Ta phrase, en une respiration","sub":"Orange, produit mobile, banque digitale, consultant AMOA"}],"takeaways":["Ton choix : banque digitale et moyens de paiement, une offre publique de mc2i.","La continuité porte sur le métier et le support mobile. Le savoir bancaire reste à acquérir, et tu le dis en premier.","Référence à citer : la banque française 100 % mobile. Laisse Orange Bank de côté.","Face au périmètre risque de Frédéric Bertrais : honnête sur la matière, précis sur la logique produit, une question à poser.","mc2i recrute sur profil : tu donnes une préférence argumentée et tu restes ouvert."],"quiz":[{"q":"Frédéric Bertrais travaille sur le risque et le crédit. Pourquoi ne pas annoncer que c'est ton sous-secteur ?","choices":["Parce que tu n'y as aucune preuve directe et que tu serais exposé dès la deuxième question.","Parce que mc2i n'a pas d'offre publique sur le risque.","Parce que le risque n'intéresse pas les consultants juniors chez mc2i."],"answer":0,"why":"L'offre risque existe bel et bien chez mc2i, et ton interlocuteur la connaît de l'intérieur. Choisir ce terrain pour plaire s'effondre à la première relance."},{"q":"Quel exemple client cites-tu pour montrer que tu connais les références mc2i en banque mobile ?","choices":["Orange Bank, puisque tu viens d'Orange et que mc2i y a travaillé.","Wero, en donnant la date de lancement du paiement marchand en France.","La banque française 100 % mobile : AMOA en Scrum, 8,5 % de transformation contre 6,5 %."],"answer":2,"why":"L'activité d'Orange Bank s'est arrêtée en 2024, et ton passage chez Orange Innovation n'a aucun lien avec. Sur Wero, les dates divergent selon les sources."},{"q":"« Que savez-vous du RCSA ? » Quelle réponse tient face à quelqu'un qui en pilote un outil ?","choices":["« C'est un sujet que j'ai croisé chez Orange, sur le suivi des risques produit. »","« Je connais le principe : les métiers auto-évaluent leurs risques et leurs contrôles. Je n'en ai pas la pratique. »","« C'est lié à Bâle et à CRR3, donc au calcul des fonds propres. »"],"answer":1,"why":"La définition courte suffit, suivie de la limite. La première réponse invente une expérience, la troisième empile du jargon qui sera creusé à la phrase suivante."}],"drill":{"prompt":"On te dit : « Vous n'avez jamais travaillé en banque. Pourquoi vous ? » Réponds à voix haute, en commençant par reconnaître le fait.","seconds":75,"model":"C'est exact, je n'ai jamais travaillé en banque, et la culture bancaire et réglementaire reste à construire. Ce que j'apporte, c'est un métier que je pratique déjà. Chez Orange Innovation, j'ai été chef de produit junior sur App Center, en appui du Product Owner, mon tuteur. Pendant deux ans, j'ai recueilli les besoins des pays et du métier sur un produit mobile, je les ai écrits en spécifications, et j'ai suivi les résultats. La banque de détail se joue aujourd'hui sur ce même support. Votre baromètre 2026 dit que l'application est devenue un prérequis. Sur un parcours d'enrôlement, la matière change, la méthode reste. C'est pour cela que je vise la banque digitale et les paiements, en consultant AMOA."},"video":"media/m04-terrain.mp4#t=0.6","mediaMinutes":4.3},{"id":"m05-reglementation","order":5,"title":"La réglementation qui compte","subtitle":"DORA, paiements, risque, IA, assurance : le texte, le projet, ton rôle","format":"video","workMinutes":11,"why":"Frédéric Bertrais a une mission DORA en banque sur son profil : à 18h, une phrase juste sur un texte rapporte plus que dix sigles.","voice":"Sulafat","scenes":[{"layout":"title","kicker":"Réglementation","heading":"Les textes qui fabriquent les projets","sub":"Le texte, l'impact projet, le rôle du junior"},{"layout":"cards","kicker":"DORA, le texte","heading":"DORA : tenir quand l'informatique lâche","items":[{"t":"Risques TIC","d":"Un cadre de gestion du risque informatique"},{"t":"Incidents","d":"Détecter, classer, notifier le superviseur"},{"t":"Tests de résilience","d":"Réguliers, et TLPT pour les entités désignées"},{"t":"Prestataires tiers","d":"Contrats, registre, dépendances suivies"},{"t":"Partage d'informations","d":"Échanges entre acteurs financiers"}]},{"layout":"stats","kicker":"DORA dans un projet","heading":"Deux chantiers : les incidents et les prestataires","items":[{"v":"4 h","l":"notification après classement majeur"},{"v":"24 h","l":"au plus tard après la détection"},{"v":"72 h","l":"rapport intermédiaire"},{"v":"19","l":"prestataires critiques, novembre 2025"}]},{"layout":"bullets","kicker":"DORA, ton rôle","heading":"Ce qu'un AMOA junior fait sur DORA","items":["Traduire les exigences en règles et en écrans","Spécifier le classement d'un incident","Fiabiliser les données du registre","Écrire les cas de test, suivre la recette","Orange sur la liste : une observation, rien de plus"]},{"layout":"cards","kicker":"Risque opérationnel","heading":"RCSA et les trois lignes de défense","items":[{"t":"RCSA","d":"Risque brut, contrôles, risque résiduel, plan d'action"},{"t":"LoD1, les métiers","d":"Propriétaires de leurs risques et de leurs contrôles"},{"t":"LoD2, le contrôle","d":"Risques et conformité : le cadre et le challenge"},{"t":"LoD3, l'audit interne","d":"Vérification indépendante de l'ensemble"}]},{"layout":"flow","kicker":"Paiements, ton terrain","heading":"Virement instantané et vérification du bénéficiaire","items":[{"t":"9 janvier 2025","d":"Tarif aligné sur le virement classique"},{"t":"9 octobre 2025","d":"Concordance du nom et de l'IBAN"},{"t":"Dans l'application","d":"Écrans, alertes, cas d'erreur"},{"t":"Wero","d":"Usage étendu au paiement en ligne"}]},{"layout":"compare","kicker":"Paiements et crédit conso","heading":"Ce qui arrive en 2028, ce qui arrive dans 11 jours","left":{"t":"DSP3 / PSR","items":["Accord politique acquis","Adoption formelle en cours","Application pas avant 2028"]},"right":{"t":"CCD2","items":["Applicable le 20 novembre 2026","Plafond porté à 100 000 €","Paiement fractionné réglementé","Contrats en cours : ancien régime"]}},{"layout":"stats","kicker":"Bâle et CRR3","heading":"CRR3 : un plancher sur les modèles internes","items":[{"v":"55 %","l":"output floor en 2026"},{"v":"72,5 %","l":"output floor en 2030"},{"v":"01/2027","l":"FRTB, risque de marché"}]},{"layout":"flow","kicker":"Crédit corporate","heading":"Comment se fabrique une note d'entreprise","items":[{"t":"Collecte","d":"Bilan, rentabilité, endettement"},{"t":"Analyse","d":"Secteur, gouvernance, jugement"},{"t":"Note","d":"Calculée, tracée, validée"},{"t":"Usages","d":"Décision de crédit, fonds propres"}]},{"layout":"cards","kicker":"Blanchiment et IA","heading":"AMLR et AI Act : deux échéances à venir","items":[{"t":"AMLR","d":"Applicable le 10 juillet 2027"},{"t":"AMLA","d":"Francfort, 40 établissements au maximum dès 2028"},{"t":"AI Act","d":"Scoring de crédit classé à haut risque"},{"t":"Échéance haut risque","d":"2 décembre 2027, selon l'accord de mai 2026"}]},{"layout":"compare","kicker":"Open finance et assurance","heading":"FIDA en suspens, Solvabilité II en approche","left":{"t":"FIDA","items":["Dossier bloqué","Retrait évoqué, non confirmé","Projet : veille"]},"right":{"t":"Solvabilité II révisée","items":["Application le 30 janvier 2027","Régime de proportionnalité","Projet : analyse d'écarts"]}},{"layout":"quote","kicker":"Ta réponse réflexe","heading":"Un texte, une date, une conséquence projet","quote":"Je connais le principe, je n'en ai pas la pratique. Sur un projet, je partirais des exigences à traduire en fonctionnalités et en reporting.","author":"Ta phrase si on te pousse sur un texte"}],"takeaways":["DORA : résilience opérationnelle numérique, cinq piliers, applicable depuis le 17 janvier 2025.","Sur tout texte, ton rôle reste le même : exigences traduites en règles, écrans, données et cas de test.","CCD2 s'applique le 20 novembre 2026 ; DSP3 et PSR, pas avant 2028 ; FIDA est bloquée et un retrait est évoqué.","RCSA : les métiers s'auto-évaluent. LoD1 conduit, LoD2 cadre et challenge, LoD3 audite.","Tu annonces toujours ce que tu sais et ce que tu n'as pas pratiqué."],"quiz":[{"q":"Tu veux relier ton expérience Orange à DORA. Quelle phrase peux-tu dire ?","choices":["« Orange étant prestataire critique, je connais le registre d'information. »","« Orange figure parmi les prestataires critiques désignés fin 2025. C'est une observation : je n'ai pas travaillé sur DORA chez Orange. »","« J'ai vu DORA de l'intérieur chez Orange, côté prestataire. »"],"answer":1,"why":"Le fait est public et sourcé. Tout ce qui laisse entendre une pratique de DORA chez Orange serait faux, et se verrait à la question suivante."},{"q":"Un crédit à la consommation est signé le 10 novembre 2026. Que se passe-t-il le 20 novembre, jour d'application de CCD2 ?","choices":["Le contrat bascule sous le nouveau régime à cette date.","Le contrat doit être signé de nouveau sous 30 jours.","Le contrat reste sous l'ancien régime."],"answer":2,"why":"Les contrats en cours au 20 novembre 2026 restent sous l'ancien régime. Pour un projet, deux régimes cohabitent donc dans le SI."},{"q":"Dans un dispositif RCSA suivi par la deuxième ligne, qui est propriétaire des risques et des contrôles ?","choices":["Les métiers, en première ligne.","La fonction risques, en deuxième ligne, puisqu'elle suit l'outil.","L'audit interne, en troisième ligne."],"answer":0,"why":"La LoD1 possède ses risques et ses contrôles. La LoD2 fixe le cadre et challenge, la LoD3 vérifie l'ensemble de façon indépendante."}],"drill":{"prompt":"À voix haute, une minute : « Que savez-vous de DORA, et que feriez-vous sur un tel projet ? »","seconds":60,"model":"DORA est le règlement européen sur la résilience opérationnelle numérique du secteur financier, applicable depuis le 17 janvier 2025. Il repose sur cinq piliers : les risques informatiques, les incidents, les tests de résilience, les prestataires tiers et le partage d'informations. Je n'en ai pas la pratique. Sur un projet, je commencerais par comprendre les exigences qui se traduisent en fonctionnalités et en reporting : par exemple, les critères de classement d'un incident majeur, ou la qualité des données du registre des contrats. Chez Orange, en appui de mon Product Owner, j'ai rapproché des chiffres entre sources et définitions pour un reporting mensuel. Je vérifierais de la même façon que tout le monde parle de la même chose. La matière réglementaire, je dois l'apprendre, et je m'y mettrai dès le départ."},"video":"media/m05-reglementation.mp4#t=0.6","mediaMinutes":5.8},{"id":"m06-preuves","order":6,"title":"Tes preuves, version Directeur","subtitle":"Orange, le cas mc2i, Nexus Ops : situation, action, résultat","format":"video","workMinutes":12,"why":"À 18h, on vérifie ce que tu as produit toi-même : chaque preuve doit tenir en 90 secondes avec ton rôle exact.","voice":"Sulafat","scenes":[{"layout":"title","kicker":"Module 6","heading":"Tes preuves, version Directeur","sub":"Ce que tu as produit, ta part exacte, ce que tu ne sais pas"},{"layout":"cards","kicker":"Ce qui a coincé","heading":"Quatre corrections depuis le 15 octobre","items":[{"t":"Ton rôle","d":"Chef de produit junior, en appui du PO. Plus de « A à Z »."},{"t":"Je et nous","d":"Je pour ton apport, nous pour le travail à six."},{"t":"Le run","d":"Livré en fin d'alternance. Pas de mesure d'usage durable."},{"t":"La longueur","d":"Une réponse : 60 à 90 secondes, puis silence."}]},{"layout":"flow","kicker":"La méthode","heading":"Un chemin, 60 à 90 secondes","items":[{"t":"Situation","d":"Une phrase de contexte"},{"t":"Action","d":"Deux ou trois phrases, avec je"},{"t":"Résultat","d":"Un fait que tu peux défendre"},{"t":"Limite","d":"Dite par toi, puis silence"}]},{"layout":"compare","kicker":"Preuve 1, Orange","heading":"Le reporting mensuel devenu dashboard","left":{"t":"Situation","items":["Reporting mensuel, 130 destinataires","Excel et PowerPoint, format statique","Définitions différentes selon les sources"]},"right":{"t":"Mon action","items":["Recueil auprès de trois pôles","Carnet de spécifications fonctionnelles","Construction du dashboard self-service"]}},{"layout":"quote","kicker":"Le run, sans trembler","heading":"Le résultat et sa limite","quote":"Le dashboard a été livré en fin d'alternance. Je n'ai pas de mesure d'usage dans la durée, seulement les premiers retours, qui étaient positifs.","author":"À dire tel quel"},{"layout":"stats","kicker":"Preuve 1 bis","heading":"Les business cases avec les filiales","items":[{"v":"5","l":"filiales"},{"v":"5 ans","l":"horizon des modèles"},{"v":"≈ 11 M€","l":"de revenus modélisés"}]},{"layout":"compare","kicker":"Face à un PO certifié","heading":"La frontière doit être nette","left":{"t":"Tu dis","items":["Recueil des besoins, spécifications","Relais auprès des équipes techniques","Échanges continus avec mon tuteur"]},"right":{"t":"Tu évites","items":["« J'étais le PO », « j'ai décidé seul »","Backlog ou sprint, si tu ne les as pas tenus","« Junior Product Manager » : dis le titre du CV"]}},{"layout":"compare","kicker":"Preuve 2, cas mc2i","heading":"Le cas mc2i : le je et le nous","left":{"t":"Je : mon apport","items":["Audit stratégique","Diagnostic et benchmark qui en viennent","Sites comparés sur critères objectifs"]},"right":{"t":"Nous, en équipe de six","items":["Drupal vers WordPress, 3 pages","SEO, GEO, agent IA","Matrice impact × effort","Roadmap à 6 mois"]}},{"layout":"cards","kicker":"Preuve 3, Nexus Ops","heading":"Un CRM cadré du besoin à la livraison","items":[{"t":"Situation","d":"Le cas d'une boutique de jeux"},{"t":"Action","d":"Conçu et développé seul, sous ma spécification"},{"t":"Méthode","d":"Assistants IA, sous mes contrôles"},{"t":"Résultat","d":"Segmentation, score santé client, campagnes RGPD"}]},{"layout":"bullets","kicker":"Le geste final","heading":"Chaque preuve finit par un pont","items":["Parcours : « la matière change, la méthode reste »","Données : « tout le monde parle de la même chose »","CRM : « segmenter, respecter le consentement »"]}],"takeaways":["Titre exact : chef de produit junior, en appui du Product Owner, mon tuteur.","Je pour l'audit stratégique, nous pour tout le reste du travail à six.","Le run en une phrase : livré en fin d'alternance, pas de mesure d'usage dans la durée, premiers retours positifs.","Toujours « ≈ 11 M€ modélisés ».","Une preuve : 60 à 90 secondes, un pont vers la banque, puis silence."],"quiz":[{"q":"On te demande : « Vous étiez donc le Product Owner du dashboard ? » Quelle réponse tient face à un PO certifié ?","choices":["« Oui, sur ce projet, je l'ai mené de A à Z de manière autonome. »","« Non. Le Product Owner était mon tuteur. J'ai pris en charge le recueil des besoins, les spécifications et la construction du dashboard. »","« Nous étions très proches, difficile de séparer les rôles. »"],"answer":1,"why":"Le « A à Z » a déjà créé un flou le 15/10, et l'esquive laisse la question ouverte. La bonne réponse sépare les rôles en une phrase."},{"q":"« Sur le cas mc2i, qu'avez-vous produit exactement ? »","choices":["« À six, nous avons travaillé sur la refonte. Mon apport propre, c'est l'audit stratégique, d'où viennent le diagnostic et le benchmark. »","« J'ai fait l'audit de 64 pages, puis j'ai priorisé les actions par impact et effort. »","« Nous avons tous tout fait ensemble, nous étions six. »"],"answer":0,"why":"« 64 pages » ne se dit pas à l'oral, et la matrice impact × effort relève du travail d'équipe. La troisième réponse efface ton apport : c'est la question posée le 15/10."},{"q":"« Combien de personnes utilisent votre dashboard ? »","choices":["« Les 130 destinataires du reporting l'ont adopté. »","« Toute l'équipe le consulte chaque jour. »","« Il a été livré en fin d'alternance. Je n'ai pas de mesure d'usage dans la durée, seulement les premiers retours, qui étaient positifs. »"],"answer":2,"why":"130, c'est le nombre de destinataires du reporting mensuel : aucune donnée n'établit l'adoption du dashboard. Annonce la limite toi-même."}],"drill":{"prompt":"Réponds à voix haute en 90 secondes maximum : « Parlez-moi de votre réalisation chez Orange et de votre rôle exact. »","seconds":90,"model":"J'étais chef de produit junior sur App Center, en appui du Product Owner, mon tuteur. Le reporting mensuel partait à 130 destinataires, en Excel et PowerPoint, et les définitions variaient selon les sources. J'ai recueilli les besoins de trois pôles : l'équipe App Center, les pays et la technique. J'ai écrit un carnet de spécifications : les rôles, ce que chacun voulait et pourquoi. Puis j'ai construit un dashboard self-service, en échangeant en continu avec mon tuteur. Le dashboard a été livré en fin d'alternance. Je n'ai pas de mesure d'usage dans la durée, seulement les premiers retours, qui étaient positifs. Avant d'afficher un indicateur, je vérifie que tout le monde parle de la même chose : c'est ce que je veux apporter en banque digitale."},"video":"media/m06-preuves.mp4#t=0.6","mediaMinutes":4},{"id":"m07-presentation","order":7,"title":"Exemple de présentation","subtitle":"Deux minutes à la première personne, puis pourquoi ça marche","format":"video","workMinutes":8,"why":"Les deux premières minutes posent ton rôle, ton terrain et ta limite avant que Frédéric Bertrais ait à les chercher.","voice":"Iapetus","scenes":[{"layout":"title","kicker":"Qui je suis","heading":"Abdelaziz Semlali","sub":"Master IAE Paris, terrain client, données"},{"layout":"flow","kicker":"Orange Innovation","heading":"Deux ans en appui du Product Owner","items":[{"t":"Recueil","d":"Besoins des pays et du métier"},{"t":"Spécifications","d":"Écrites en fonctionnel"},{"t":"Relais","d":"Vers les équipes techniques"}]},{"layout":"stats","kicker":"Deux réalisations","heading":"Ce que je peux montrer","items":[{"v":"5","l":"filiales en business cases"},{"v":"≈ 11 M€","l":"de revenus modélisés"},{"v":"130","l":"destinataires du reporting mensuel"}]},{"layout":"compare","kicker":"Hors alternance","heading":"Le groupe, et ce que j'ai fait seul","left":{"t":"En équipe de six","items":["Refonte du site de mc2i","Défendue devant la direction de mc2i"]},"right":{"t":"Je","items":["L'audit stratégique du cas mc2i","Nexus Ops, conçu et développé seul"]}},{"layout":"quote","kicker":"Banque digitale et paiements","heading":"L'application ne suffit plus à se différencier","quote":"Simplement devenue un prérequis invisible.","author":"Baromètre de la Banque de demain 2026, mc2i"},{"layout":"compare","kicker":"Ce que je construis","heading":"Ce que j'ai, ce qui me reste à acquérir","left":{"t":"Acquis","items":["Recueil des besoins, spécifications","Produit mobile, données fiables"]},"right":{"t":"À construire","items":["Culture bancaire","Pratique du réglementaire"]}},{"layout":"cards","kicker":"Pourquoi mc2i","heading":"Trois raisons, une projection","items":[{"t":"Opérationnel","d":"Le niveau d'intervention où je veux apprendre"},{"t":"Indépendance","d":"Libres de conseiller ce qui convient au client"},{"t":"Proximité","d":"Un encadrant qui connaît mon contexte"},{"t":"Dans cinq ans","d":"Consultant senior au pôle Banque Finance Assurance"}]},{"layout":"cards","kicker":"Décryptage","heading":"Ce que cette présentation fait","items":[{"t":"Rôle exact","d":"Titre du CV et « en appui » dès le début"},{"t":"Je et nous","d":"Chaque mérite attribué au bon niveau"},{"t":"Sous-secteur","d":"Répond à la question annoncée le 15/10"},{"t":"Limite","d":"Dite avant qu'on la pointe : le pivot se dégonfle"},{"t":"Projection","d":"Secteur et poste, là où le 15/10 restait flou"}]}],"takeaways":["Sept blocs : parcours, Orange, réalisations, cas mc2i et Nexus, banque digitale, limite, mc2i.","Dis ta limite bancaire avant qu'on te la pointe.","Termine ta dernière phrase, puis silence. Aucun commentaire sur la durée.","Si on te demande une minute, garde Orange, le pont banque digitale et la limite."],"quiz":[{"q":"Tu finis ta présentation et ton interlocuteur ne dit rien pendant trois secondes. Que fais-tu ?","choices":["« Je ne sais pas si j'ai été trop long. »","Tu attends, en silence, avec le regard posé.","Tu ajoutes un projet pour remplir le blanc."],"answer":1,"why":"Le 15/10, tu as commenté ta propre réponse : « Je ne sais pas si j'ai été trop court ». Termine la phrase et tais-toi."},{"q":"Comment citer le cas mc2i dans la présentation ?","choices":["« J'ai réalisé pour vous un audit de 64 pages. »","« J'ai refondu le site de mc2i dans le cadre de mon master. »","« En équipe de six, nous avons travaillé sur la refonte de votre site, défendue devant la direction de mc2i. J'y ai réalisé l'audit stratégique. »"],"answer":2,"why":"Le travail de groupe doit être crédité comme tel, puis ton apport nommé. « 64 pages » ne se dit pas à l'oral."},{"q":"Pourquoi dire « je n'ai pas encore la culture bancaire » dans la présentation ?","choices":["Parce que ton CV le montre déjà : tu en fais un point maîtrisé et tu enchaînes sur ce que tu viens construire.","Parce qu'il faut paraître humble, quel que soit le sujet.","Pour pousser ton interlocuteur à proposer une mission hors banque."],"answer":0,"why":"Frédéric Bertrais verra sur le CV que tu n'as jamais travaillé en banque. Le dire d'abord te laisse la main sur la suite."}],"drill":{"prompt":"Présente-toi à voix haute, chronomètre lancé, sans lire. Objectif : deux minutes, dernière phrase terminée, puis silence.","seconds":120,"model":"Bonjour, je suis Abdelaziz Semlali, diplômé du Master Marketing et Stratégie Business de l'IAE Paris. Avant cela, j'ai été conseiller de vente chez Leroy Merlin et j'ai créé une boutique en ligne. J'y ai appris à écouter un client et à suivre mes données de bout en bout. Pendant deux ans, en alternance chez Orange Innovation, j'ai été chef de produit junior sur App Center, en appui du Product Owner, mon tuteur. J'ai recueilli les besoins des pays et du métier, écrit les spécifications fonctionnelles et assuré le relais auprès des équipes techniques. Deux réalisations résument cette période. J'ai construit des business cases avec cinq filiales, sur cinq ans, pour environ 11 M€ de revenus modélisés. Et le reporting mensuel, envoyé à 130 destinataires, a été refondu en dashboard self-service, après avoir mis en cohérence les définitions entre les sources. Je connais déjà mc2i par la pratique. En équipe de six, nous avons travaillé sur la refonte de votre site, défendue devant la direction de mc2i. J'y ai réalisé l'audit stratégique, d'où viennent le diagnostic et le benchmark. J'ai aussi conçu et développé seul Nexus Ops, un CRM sur mesure, avec des assistants IA, sous ma spécification et mes contrôles. Je veux rejoindre la banque digitale et les paiements. La banque de détail se joue aujourd'hui sur le mobile : l'application, l'enrôlement, la souscription, la relation client. Votre baromètre 2026 dit que l'application est devenue un prérequis. C'est le support que j'ai pratiqué pendant deux ans. Ce que je n'ai pas encore, c'est la culture bancaire et réglementaire. Je connais les enjeux de DORA ou du virement instantané, je ne les ai pas pratiqués en mission. C'est ce que je viens construire au pôle Banque Finance Assurance, à partir d'un métier que je pratique déjà. mc2i intervient au niveau opérationnel des projets, c'est là que je veux apprendre. Votre indépendance vous laisse libres de conseiller ce qui convient au client. Votre encadrement de proximité me donne un cadre pour progresser. Dans cinq ans, je me vois consultant senior au pôle, avec une expertise reconnue sur mon domaine. Je suis disponible immédiatement."},"video":"media/m07-presentation.mp4#t=0.6","mediaMinutes":2.5},{"id":"m08-express","order":8,"title":"Entretien express (30 min en répondant)","subtitle":"Une simulation complète avec un Directeur fictif, exigeant et bienveillant","format":"dialogue","workMinutes":30,"why":"Tu entends une fois le rythme entier de 18h, avec les relances qui font mal et des réponses à imiter.","parts":[{"title":"Présentation, parcours et rôle chez Orange","turns":[{"s":"D","t":"Bonjour Abdelaziz, merci d'être là. Nous avons environ une heure devant nous. Je vais vous challenger un peu, c'est le principe de ce tour. Présentez-vous, en deux minutes maximum.","at":0.05},{"s":"C","t":"Bonjour, merci de me recevoir. Je suis diplômé du Master Marketing et stratégie business de l'IAE Paris. J'ai passé deux ans en alternance chez Orange Innovation, comme chef de produit junior sur App Center, en appui du Product Owner, mon tuteur. App Center installe des applications sur les téléphones vendus par Orange et ses partenaires. Ma place était entre les équipes techniques, le métier et les filiales pays. J'ai recueilli leurs besoins, écrit des spécifications, consolidé le reporting mensuel et construit des business cases avec cinq filiales. J'ai connu mc2i pendant mon master, par des cours donnés par vos collaborateurs. Nous avons ensuite travaillé en équipe de six sur la refonte de votre site, un cas défendu devant votre direction. Aujourd'hui, je veux mettre cette pratique au service de la banque digitale et des paiements, en consultant AMOA.","at":8.2},{"s":"D","t":"Merci, c'est clair. Votre formation est marketing, et vous postulez sur un métier très proche du système d'information. Comment avez-vous fait ce chemin ?","at":52.48},{"s":"C","t":"Le lien existait dès le départ. Après une licence d'économie-gestion à Orléans, j'ai hésité entre un master en management des systèmes d'information et le master en stratégie business et marketing. J'ai choisi le second, parce que je voulais comprendre le client et la valeur d'un produit. Pendant mes études, j'ai aussi été conseiller de vente chez Leroy Merlin, seul au rayon le dimanche, avec plus de trente clients par jour. J'y ai appris à parler à des profils très différents. Chez Orange, les deux versants se sont rejoints. Je devais comprendre un besoin métier, puis l'expliquer à des équipes techniques. C'est la partie de mon travail que j'ai préférée, et c'est celle que je veux développer.","at":59.26},{"s":"D","t":"Je vois aussi une activité d'auto-entrepreneur, Beauty'ly. Pourquoi avoir arrêté ?","at":96.46},{"s":"C","t":"J'ai créé la marque et la boutique en ligne, avec l'identité, les contenus et des campagnes TikTok Ads. Le chiffre d'affaires est resté à quatre chiffres. L'effort dépassait le revenu, et je ne pouvais pas garantir les retours clients avec un fournisseur en Chine. J'ai arrêté. Ce projet m'a appris à suivre mes données de bout en bout, et à prendre une décision sur ces données, y compris celle de m'arrêter.","at":101.62},{"s":"D","t":"Avant d'aller plus loin chez Orange, expliquez-moi App Center comme à quelqu'un qui n'en a jamais entendu parler. À quoi sert ce produit, et qui décide quoi ?","at":121.68},{"s":"C","t":"App Center permet d'installer des applications sur les téléphones vendus par les canaux d'Orange et par ses partenaires. Le produit a deux objectifs : personnaliser l'expérience de l'utilisateur, et générer du revenu grâce à des applications partenaires. La difficulté tient à l'organisation. Les contrats sont signés au niveau du groupe, et chaque pays les applique ensuite chez lui, avec son marché et ses règles. Il y a donc un seul produit et plusieurs réalités locales. Mon travail consistait à faire circuler l'information entre l'équipe App Center, les équipes techniques et les représentants pays, pour que chacun décide avec les mêmes éléments.","at":130.25},{"s":"D","t":"Bien. Venons-en à Orange. Sur quoi passiez-vous concrètement votre temps ?","at":161.58},{"s":"C","t":"Sur deux sujets principaux. Le premier était le reporting mensuel, envoyé à cent trente destinataires. Je collectais des données venant de plusieurs sources et de plusieurs interlocuteurs, et je devais concilier leurs définitions, parce qu'un même indicateur ne voulait pas dire la même chose partout. Le second était les business cases avec cinq filiales. Les pays voulaient savoir si l'intégration d'une application partenaire valait la peine. Je collectais leurs besoins et leurs données, je faisais des benchmarks, puis je construisais un modèle à cinq ans. Ces travaux représentent environ onze millions d'euros de revenus modélisés. L'objectif était de montrer aux pays que le coût de la non-action était plus élevé que le coût de l'action. Les contrats étaient signés au niveau du groupe, puis appliqués localement, ce qui m'obligeait à vérifier les contrats et les règles de chaque pays.","at":163.98},{"s":"D","t":"Onze millions. Vous les avez vus arriver, ces revenus ?","at":205.26},{"s":"C","t":"Non, et je tiens à être précis. Ce sont des revenus modélisés, sur cinq ans et sur cinq filiales. Je n'ai pas de revenu réalisé à vous citer. La valeur de ce travail était d'éclairer la décision d'un pays avec des hypothèses explicites. Je peux vous détailler la méthode : les besoins et les données collectés auprès du pays, le benchmark, les hypothèses de revenus, puis la comparaison entre agir et ne rien faire.","at":208.5},{"s":"D","t":"Ces données, comment les obteniez-vous auprès des filiales ?","at":227.52},{"s":"C","t":"Par les représentants pays, qui étaient mes interlocuteurs directs. Je partais de leur question : cette intégration vaut-elle la peine chez nous ? Je leur demandais les données dont ils disposaient, puis je complétais avec un benchmark et avec la lecture des contrats et des règles locales. Les hypothèses restaient écrites dans le modèle, pour que le pays puisse les discuter. J'y ai appris qu'un chiffre convainc mieux quand la personne en face peut voir d'où il vient.","at":230.68},{"s":"D","t":"Vous écrivez « en appui du Product Owner ». Soyons concrets. Qu'est-ce qui était à vous, et qu'est-ce qui était à lui ?","at":251.92},{"s":"C","t":"Les décisions sur le produit revenaient au Product Owner, mon tuteur, avec qui j'échangeais en continu. En appui, j'ai pris en charge le recueil des besoins, les spécifications et la construction du dashboard. Les business cases, je les ai construits avec les pays. Il y a aussi des sujets où mon rôle était plus limité. Sur les effets de la DMA, de l'AI Act et du consentement, j'étais en appui et je n'étais pas le seul contributeur. C'est pour cette raison que je ne les ai pas mis sur mon CV. Je préfère vous présenter ce que je peux défendre jusque dans le détail.","at":259.21}],"note":"Remarque trois choses. Le titre exact, « chef de produit junior », et « en appui du Product Owner, mon tuteur » arrivent dès la première minute. « Modélisés » vient sans qu'on le réclame, et la relance sur les onze millions se gère en disant non tout de suite. Le 15 octobre, tu avais dit « mené de A à Z » : ici, tu sépares proprement ce qui était à toi et ce qui ne l'était pas. Beauty'ly tient en cinq phrases courtes, puis tu te tais.","audio":"media/m08-express-1.mp3","duration":286.54},{"title":"Du reporting au dashboard, cas mc2i, travail d'équipe","turns":[{"s":"D","t":"Racontez-moi le passage du reporting au dashboard. Pourquoi ce changement, et qu'avez-vous fait vous-même ?","at":0.15},{"s":"C","t":"Au départ, le reporting était un fichier statique, entre Excel et PowerPoint, envoyé chaque mois à cent trente destinataires. Chaque mois, il était adapté aux messages à porter. Ce format provoquait beaucoup de questions des pays, et c'est ce qui a motivé la refonte. J'ai commencé par le recueil des besoins, auprès de trois pôles : l'équipe App Center, les représentants pays et la technique. Les trois avaient besoin de données, et de données différentes. J'ai écrit un carnet de spécifications fonctionnelles, qui précisait les rôles de chacun, ce qu'il voulait et pourquoi il le voulait. Ensuite, j'ai construit un dashboard web en self-service, organisé autour des questions récurrentes des filiales. Le point le plus utile a été d'aligner les définitions. Avant d'afficher un indicateur, je vérifie que tout le monde parle de la même chose.","at":5.82},{"s":"D","t":"Et le résultat ? Combien de personnes l'utilisent réellement ?","at":48.3},{"s":"C","t":"Je n'ai pas ce chiffre. Le dashboard a été livré en fin d'alternance. Je n'ai pas assuré le run, et je n'ai pas de mesure d'usage dans la durée, seulement les premiers retours, qui étaient positifs. C'est une limite de ce projet, et j'en retiens quelque chose. Si je devais le refaire, je définirais dès le cadrage l'indicateur d'usage à suivre et la personne qui le suivrait après la livraison. Un outil livré sans mesure d'adoption laisse une question ouverte.","at":52.42},{"s":"D","t":"J'apprécie la franchise. Techniquement, tout était en VBA ?","at":75.64},{"s":"C","t":"En partie. J'ai utilisé VBA pour appliquer des règles à des classeurs entiers, parce que les sources étaient éclatées et que certaines demandaient des ajustements manuels. J'ai aussi participé à la migration d'un tableau de Google Analytics vers Kibana, en vérifiant que les filtres et les définitions restaient les mêmes. Du côté de l'IA, seul l'outil interne était autorisé, donc l'automatisation restait partielle. En fin d'alternance, j'ai eu accès à Claude Code dans un programme pilote, après que nous avons poussé avec d'autres personnes en interne pour obtenir des outils plus agentiques. Je garde de tout cela une habitude : automatiser ce qui est répétitif, et contrôler moi-même ce qui engage un chiffre.","at":77.84},{"s":"D","t":"Parlons du cas sur notre site. Vous étiez six. Qu'avez-vous produit exactement ?","at":114.44},{"s":"C","t":"Mon apport propre, c'est l'audit stratégique, d'où viennent le diagnostic et le benchmark. J'ai analysé d'autres sites, je les ai classés par catégories et je les ai notés sur des critères objectifs. Le reste est un travail d'équipe, et je tiens à le créditer ainsi. À six, nous avons recommandé de passer de Drupal à WordPress, pour redonner la main au marketing. Nous avons conçu trois pages clés, travaillé le SEO et le GEO, et proposé un agent IA. Ensuite, nous avons priorisé les actions avec une matrice impact fois effort, et construit une roadmap à six mois. Nous l'avons défendue devant votre direction. La priorisation répondait à un risque que je trouve classique : un projet qui tourne pendant deux ans sans amélioration visible finit par perdre ses soutiens. Si cela vous est utile, je peux vous transmettre l'étude.","at":120.03},{"s":"D","t":"Pourquoi avoir commencé par l'impact et l'effort, plutôt que par le choix de l'outil ?","at":162.86},{"s":"C","t":"Parce que l'outil n'a de sens qu'une fois le besoin posé. Le site sert deux publics qui n'attendent pas la même chose : les décideurs de grands groupes et les candidats. Nous avions donc beaucoup d'idées possibles, et une capacité de réalisation forcément limitée. La matrice nous a obligés à comparer ce que chaque action apportait et ce qu'elle demandait, et à placer des gains rapides au début de la roadmap. C'est aussi ce qui rendait la recommandation discutable par votre direction, parce que le raisonnement était visible.","at":166.8},{"s":"D","t":"Dans un groupe de six, il y a des frictions. Donnez-moi un moment où vous n'étiez pas d'accord avec quelqu'un.","at":192.82},{"s":"C","t":"Sur ce cas, je n'ai pas de conflit marquant à vous citer, et je préfère ne pas en fabriquer un. L'exemple le plus parlant vient d'Orange. Les trois pôles qui utilisaient le reporting avaient des attentes qui ne se recoupaient pas, et un même indicateur pouvait être défini de plusieurs façons. Je ne pouvais satisfaire personne en empilant les demandes. J'ai repris chaque besoin avec eux, j'ai noté qui voulait quoi et pourquoi, en échangeant en continu avec mon tuteur. J'en retiens qu'un désaccord porte souvent sur une définition que personne n'a écrite. Une fois écrite, la discussion devient plus simple.","at":197.68},{"s":"D","t":"Dernière chose sur vos projets. Votre CRM, Nexus Ops, et votre portfolio : comment les avez-vous construits ?","at":229.04},{"s":"C","t":"Nexus Ops est un CRM sur mesure, pour le cas d'une boutique de jeux, conçu et développé seul, avec des assistants IA, sous ma spécification et mes contrôles. J'ai cadré le besoin, écrit la spécification, puis vérifié ce qui était produit. On y trouve la segmentation, un score de santé client et des campagnes conçues sous contrainte RGPD. Le portfolio est fait de la même manière. Ce qui m'intéresse dans ces outils, c'est qu'ils rendent la qualité de la spécification immédiatement visible : un besoin mal écrit donne un résultat faux.","at":233.7},{"s":"D","t":"Votre mémoire porte sur l'IA agentique. En quoi cela peut-il servir un client bancaire ?","at":262.82},{"s":"C","t":"Mon mémoire portait sur l'IA agentique dans l'aide à la décision des juniors en marketing. La question qui me reste pour la banque, c'est celle de la responsabilité : qui répond d'une décision quand un outil la prépare ? Votre baromètre montre que quarante-quatre pour cent des Français resteraient fidèles si la banque remplaçait ses conseillers par des IA, à condition d'une baisse des tarifs et d'une hausse des performances. Côté réglementaire, le scoring de crédit fait partie des systèmes à haut risque de l'AI Act, avec une échéance à décembre 2027 selon l'accord provisoire de mai 2026. Pour une AMOA, cela revient à spécifier ce que l'outil propose et ce que l'humain valide.","at":267.93}],"note":"Sur le résultat du dashboard, tu réponds « je n'ai pas ce chiffre » et tu tiens : la franchise rapporte plus qu'un chiffre arrangé. Sur le cas mc2i, écoute l'ordre : ton audit d'abord, puis « à six, nous ». Marion Auger t'avait posé exactement cette question et tu avais glissé vers « ce que j'ai fait, c'était de prioriser ». Sur la friction, la réponse refuse d'inventer et bascule vers un exemple réel. Si tu as un souvenir précis et vrai d'un désaccord, utilise-le à la place.","audio":"media/m08-express-2.mp3","duration":302.46},{"title":"Conseil, mc2i, métier AMOA et sous-secteur","turns":[{"s":"D","t":"Pourquoi le conseil ? Vous sortez d'un environnement produit qui semblait vous plaire.","at":0.15},{"s":"C","t":"Ce que j'ai préféré chez Orange, c'est mettre d'accord des pays, le métier et la technique sur un besoin clair. Le conseil me permet de faire ce travail sur plusieurs projets, avec des méthodes éprouvées et des personnes plus expérimentées que moi. Le modèle de mission m'expose vite à plusieurs phases de projet et à plusieurs clients, avec un encadrant qui connaît mon contexte. Je veux devenir solide sur le fonctionnel, puis évoluer vers le pilotage de projet.","at":4.44},{"s":"D","t":"Vous pourriez faire cela directement dans une banque. Où en est votre recherche ?","at":27.38},{"s":"C","t":"Ma recherche porte sur le conseil, et mc2i est mon processus le plus avancé. Une banque m'apprendrait son propre système en profondeur, et je vois l'intérêt de ce chemin. À mon stade, je cherche autre chose. Je veux voir plusieurs organisations, plusieurs manières de cadrer un besoin et de conduire une recette, afin de comparer ce qui fonctionne et de construire mes propres repères.","at":31.74},{"s":"D","t":"D'accord. Et pourquoi mc2i ? Il y a beaucoup de cabinets sur ce marché.","at":52.4},{"s":"C","t":"J'ai trois raisons. D'abord, mc2i intervient au niveau opérationnel des projets, et c'est là que je veux apprendre. Ensuite, vous êtes indépendants et vous ne vendez pas de solution, donc vous êtes libres de conseiller ce qui convient au client. C'est cohérent avec un actionnariat détenu à cent pour cent par les managers et les collaborateurs. Enfin, je vous connais déjà. Vos collaborateurs sont intervenus dans mon master, et nous avons travaillé en équipe de six sur la refonte de votre site. Le recrutement sur profil, le management de proximité et le club Banque Finance Assurance me donnent un cadre pour progresser. Pendant mon premier entretien, Marion Auger a parlé de bagage commun et d'encadrement sur la mission. C'est exactement ce que je recherche à mon niveau.","at":56.6},{"s":"D","t":"Expliquez-moi l'AMOA, sans réciter une définition. Que fait-on de ses journées ?","at":96.5},{"s":"C","t":"L'AMOA aide le client métier, la maîtrise d'ouvrage, à exprimer, formaliser et suivre son besoin pendant tout le projet. En pratique, on anime des ateliers avec les utilisateurs, puis on décrit les fonctionnalités attendues, leurs règles de gestion, les données et les interfaces, pour que la maîtrise d'œuvre puisse construire. Ensuite, on revient vers le métier pour vérifier que ce qui est livré correspond à ce qui a été demandé. Cela passe par des spécifications fonctionnelles, un plan de recette, des cas de test, un suivi des anomalies et un procès-verbal de recette. Chez Orange, mon carnet de spécifications pour le dashboard relevait de cette logique, à plus petite échelle.","at":100.74},{"s":"D","t":"Avez-vous déjà fait de la recette ?","at":137.1},{"s":"C","t":"Mon expérience se limite à ma participation aux tests d'applications chez Orange. Je n'ai pas piloté de campagne de recette, et je ne veux pas vous laisser croire le contraire. Je comprends la logique : chaque niveau de test répond à un niveau de conception, et le cahier de recette permet au métier de valider sur des cas écrits, avec des données et un résultat attendu. C'est un des premiers savoir-faire que je souhaite consolider en mission.","at":139.33},{"s":"D","t":"Quelle différence faites-vous entre AMOA et Product Owner ? Chez nos clients, les deux mots circulent.","at":161.3},{"s":"C","t":"Le Product Owner porte la valeur du produit et le backlog, avec des user stories et des critères d'acceptation. Il décide de ce qui passe en premier. L'AMOA, ou le business analyst en mode agile, produit les exigences, les flux et les règles, souvent en soutien de ce rôle. Dans les faits, les deux se recouvrent, et le travail de traduction reste le même. Il se découpe seulement en itérations. J'ai vu ce rôle de près, puisque j'étais en appui d'un Product Owner pendant deux ans. Je n'ai pas de certification Scrum aujourd'hui, et c'est un point que j'aimerais renforcer avec vos formations.","at":165.36},{"s":"D","t":"Marion Auger vous l'a annoncé : est-ce que n'importe quel projet vous plaît ? Banque, assurance, crédit, risque, marchés. Que voulez-vous faire ?","at":194.54},{"s":"C","t":"La banque digitale et les moyens de paiement : l'enrôlement, la souscription, la vie du compte, le CRM. La banque de détail se joue maintenant sur le mobile, et c'est le support que je connais. Votre baromètre 2026 dit que l'application est devenue un prérequis, donc l'enjeu se déplace vers le parcours et la relation client. Le virement instantané en donne une bonne illustration. Depuis octobre 2025, la vérification du bénéficiaire ajoute un contrôle de concordance entre le nom et l'IBAN. Pour une AMOA, cela représente des règles à spécifier, des messages à écrire et des cas à recetter. Vous publiez aussi une référence sur une banque 100 % mobile, avec des consultants AMOA en équipes Scrum, sur ces mêmes parcours. Ce qui m'attire enfin, c'est la contrainte. Chez Orange, une règle locale de consentement en Pologne m'a obligé à réduire la base réellement adressable dans un business case. En banque, ce type de contrainte est partout.","at":203.34},{"s":"D","t":"Vous n'avez jamais travaillé en banque. Pourquoi vous mettrait-on sur ces projets ?","at":250.84},{"s":"C","t":"Vous avez raison, et je préfère le dire clairement : je n'ai pas d'expérience bancaire. La continuité porte sur le métier et sur le support. J'ai recueilli des besoins, écrit des parcours et des spécifications pour un produit mobile, et j'ai travaillé entre le métier, la technique et des filiales. Sur l'enrôlement, la matière change et la méthode reste. Ce qui me manque, c'est la culture bancaire et réglementaire. C'est ce que je viens construire chez mc2i, et j'ai commencé à le faire.","at":256.68},{"s":"D","t":"Et si on vous propose du risque ou de l'assurance ?","at":278.8},{"s":"C","t":"J'irai volontiers. Je sais que vous recrutez sur profil. Sur un outil de risque, je retrouve des utilisateurs à comprendre, des règles à spécifier et un reporting qui doit être juste. La matière, je devrai l'apprendre, et je m'y mettrai dès le départ. La banque digitale est l'endroit où je serai utile le plus vite. Je vous donne une préférence argumentée, et je n'en fais pas une condition.","at":282.95}],"note":"Le passage décisif pour 18h. Le 15 octobre, tu n'avais cité aucun sous-secteur : ici, la réponse tombe dès la première phrase, avec un exemple de règle réelle traduite en travail d'AMOA. Remarque que tu reconnais l'absence d'expérience bancaire avant qu'elle soit retournée contre toi. Sur la recette, tu ne bluffes pas : Frédéric Bertrais a signé en 2012 une tribune sur les outils de recette, et ton interlocuteur a la certification Product Owner. Les deux réponses les plus techniques sont donc celles où l'honnêteté compte le plus.","audio":"media/m08-express-3.mp3","duration":304.26},{"title":"DORA, projection, salaire, questions et conclusion","turns":[{"s":"D","t":"Vous citiez la réglementation. Parlons de DORA. Que pouvez-vous m'en dire ?","at":0.15},{"s":"C","t":"DORA porte sur la résilience opérationnelle numérique du secteur financier européen, banques et assurances comprises. Le règlement s'applique depuis le dix-sept janvier 2025. Je retiens cinq piliers : la gestion des risques informatiques, la gestion et la notification des incidents, les tests de résilience, les risques liés aux prestataires tiers et le partage d'informations. Je l'ai travaillé en préparant nos échanges, et je n'en ai pas la pratique. Je ne vais donc pas vous présenter cela comme une compétence. Sur un projet, je commencerais par comprendre quelles exigences se traduisent en fonctionnalités et en reporting.","at":4.48},{"s":"D","t":"Justement. Donnez-moi un exemple d'exigence qui se traduit en travail fonctionnel.","at":34.06},{"s":"C","t":"Je prendrais le registre d'information. C'est l'inventaire des contrats avec les prestataires informatiques, remis au superviseur. Derrière ce registre, je vois un sujet que je connais à plus petite échelle : des données dispersées, plusieurs contributeurs et des définitions à aligner. Il faut savoir ce qu'on appelle un prestataire, qui renseigne l'information et qui la contrôle. La notification des incidents majeurs est un autre exemple, avec des délais courts, qui demandent un circuit de classification clair. J'ai aussi noté qu'Orange figure sur la liste des prestataires critiques publiée en novembre 2025. Je n'ai pas travaillé sur DORA chez Orange. Ce détail m'a simplement fait mesurer que le sujet touche aussi des acteurs hors de la finance.","at":38.44},{"s":"D","t":"C'est honnête, et c'est suffisant pour un junior. Où vous voyez-vous dans trois ans ?","at":74.04},{"s":"C","t":"Dans trois ans, je me vois consultant confirmé au pôle Banque Finance Assurance, solide sur le fonctionnel, avec une première expertise sur la banque digitale et les paiements. J'aurais vu plusieurs phases de projet, du cadrage à la recette et au déploiement, chez plusieurs clients. Je commencerais à coordonner un périmètre de bout en bout et à accompagner des consultants arrivés après moi, pour évoluer vers le pilotage de projet. J'aimerais aussi avoir élargi mon expertise vers le réglementaire ou les outils risque, par le club et par les missions. Je veux m'inscrire dans la durée dans un cabinet où l'on progresse par les projets.","at":78.76},{"s":"D","t":"Quels sont vos axes de progrès, sérieusement ?","at":108.36},{"s":"C","t":"Il y en a deux. Le premier est la culture bancaire et réglementaire. Je la construis, et je sais qu'elle prendra du temps. Le second concerne ma synthèse à l'oral. J'ai tendance à donner beaucoup de contexte avant d'arriver au point. Depuis mon premier entretien, je m'entraîne à donner la réponse d'abord, puis le détail si on me le demande. En mission, c'est une compétence utile en comité, quand les participants ont peu de temps.","at":110.8},{"s":"D","t":"Côté pratique. Vous êtes basé où, et une mission en anglais vous poserait-elle problème ?","at":132.82},{"s":"C","t":"Je suis à Paris, et je suis ouvert à une mobilité internationale. Une mission en anglais me conviendrait sans difficulté : j'ai un niveau C2, et j'ai grandi au Maroc avec des cours en arabe, en anglais et en français. Je parle aussi espagnol, au niveau B1. Chez Orange, je travaillais déjà avec des représentants de plusieurs pays. Je suis disponible immédiatement, donc je peux commencer dès qu'une mission se présente.","at":137.87},{"s":"D","t":"Parlons rémunération. Quelles sont vos prétentions ?","at":159.48},{"s":"C","t":"Je vise une fourchette de quarante-quatre à quarante-six mille euros brut fixe, pour un poste de consultant à Paris.","at":162.82},{"s":"D","t":"C'est noté, nous en reparlerons. Quelles questions avez-vous pour moi ?","at":168.72},{"s":"C","t":"J'en ai deux. La première concerne les débuts. Pour un consultant junior au pôle Banque Finance Assurance, à quoi ressemble une première mission, quelle est sa durée habituelle, et combien de temps s'écoule en général entre l'arrivée et le démarrage ? La seconde porte sur le métier. J'ai vu que le pôle intervient sur des outils risque en mode produit. Sur un outil comme le suivi des contrôles RCSA, qu'est-ce qui rend le rôle de Product Owner difficile par rapport à un produit grand public ?","at":172.96},{"s":"D","t":"Sur la durée, cela dépend beaucoup des clients. Sur la seconde, vos utilisateurs connaissent leur métier mieux que vous, et une erreur de donnée se voit tout de suite. Qu'est-ce que cela vous évoque ?","at":199.16},{"s":"C","t":"Cela me rappelle mon reporting, à une échelle beaucoup plus modeste. Quand un indicateur n'avait pas la même définition selon les pays, la discussion se déplaçait vers la confiance dans le chiffre. Je ne connais pas le métier du risque opérationnel. Je retiens de votre réponse qu'il faudrait d'abord gagner la crédibilité auprès des utilisateurs, en apprenant leur vocabulaire et en livrant une donnée fiable. C'est ce par quoi je commencerais.","at":207.88},{"s":"D","t":"Très bien. Un dernier mot avant de nous quitter ?","at":229.84},{"s":"C","t":"Merci beaucoup pour cet échange. Je vous apporte une pratique réelle du recueil des besoins, de la spécification et de la coordination entre le métier, la technique et des pays, sur un produit mobile. Je sais ce qu'il me reste à apprendre sur la banque, et je veux l'apprendre chez mc2i, sur la banque digitale et les paiements. Si l'étude sur votre site peut vous être utile, je vous la transmets. Pouvez-vous me dire quelle est la suite du processus ?","at":232.42}],"note":"Sur DORA, écoute le mouvement : ce que tu sais, ce que tu n'as pas pratiqué, ce que tu ferais. Le lien avec Orange s'accompagne toujours de la phrase « je n'ai pas travaillé sur DORA chez Orange ». Sur le salaire, tu attends la question, tu donnes la fourchette, puis tu te tais. Les réponses du Directeur aux questions du candidat sont inventées : à 18h, écoute les vraies et rebondis comme ici. Termine par la suite du processus, sans ajouter « je ne sais pas si j'ai été clair ».","audio":"media/m08-express-4.mp3","duration":256.6}],"takeaways":["Commence chaque réponse par le fait, puis le détail seulement si on le demande.","Dis d'emblée « en appui », « modélisés » et « en équipe de six » : la relance perd sa force.","Quand tu n'as pas le chiffre ou la pratique, dis-le en une phrase et enchaîne sur ce que tu ferais.","Le sous-secteur tombe dès la première phrase : banque digitale et moyens de paiement, une préférence argumentée.","Le salaire attend la question : quarante-quatre à quarante-six mille euros brut fixe, puis silence."],"quiz":[{"q":"Le Directeur demande : « Votre dashboard, il a eu quel impact ? » Quelle réponse tient sous la relance ?","choices":["« Les 130 destinataires ont gagné du temps chaque mois, et les questions des pays ont nettement baissé. »","« Livré en fin d'alternance, je n'ai pas de mesure d'usage dans la durée, seulement de premiers retours positifs. »","« Le projet a été un succès, puisque je l'ai mené de A à Z en autonomie pendant toute l'alternance. »"],"answer":1,"why":"La première semble solide, mais aucune source ne mesure ce gain ni cette baisse. La troisième reprend la formule du 15 octobre, celle qui contredit « en appui du Product Owner »."},{"q":"Tu veux utiliser le fait qu'Orange figure sur la liste des prestataires critiques DORA. Quelle formulation est juste ?","choices":["« Comme Orange est prestataire critique, j'ai été exposé à DORA pendant mon alternance. »","« J'ai travaillé chez un prestataire critique, je connais donc la vision des tiers dans DORA. »","« Orange figure sur la liste de novembre 2025. Je n'ai pas travaillé sur DORA chez Orange, mais le fait m'a parlé. »"],"answer":2,"why":"Les deux autres laissent entendre une pratique que tu n'as pas. Ton travail réglementaire chez Orange portait sur la DMA, l'AI Act et le consentement, et toujours en appui."},{"q":"« Sur le cas mc2i, qu'avez-vous produit exactement ? » Quelle réponse respecte ce que tu peux affirmer ?","choices":["« Mon apport propre, c'est l'audit stratégique, d'où viennent diagnostic et benchmark. À six, nous avons priorisé avec la matrice impact × effort. »","« J'ai réalisé l'audit, puis j'ai fait la priorisation par impact et effort, et l'équipe a repris mes conclusions dans la roadmap. »","« Nous avons tout construit ensemble à six, il est difficile d'isoler ma contribution, mais j'ai beaucoup participé au benchmark. »"],"answer":0,"why":"La deuxième te crédite d'une matrice faite en équipe. La troisième efface ton apport, alors que la question te demande justement de le nommer."}],"drill":{"prompt":"Coupe le son, regarde la caméra et réponds à voix haute à la relance la plus dure : « Vous n'avez jamais travaillé en banque. Pourquoi vous mettrait-on sur un projet de banque digitale ? » Enchaîne sur ton sous-secteur, sans notes.","seconds":60,"model":"Vous avez raison, je n'ai pas d'expérience bancaire. La continuité porte sur le métier et sur le support. Pendant deux ans chez Orange, en appui du Product Owner, mon tuteur, j'ai recueilli les besoins des pays et du métier sur un produit mobile, et je les ai écrits en spécifications. La banque de détail se joue aujourd'hui sur ce support : l'application, l'enrôlement, la souscription, la relation client. Sur l'enrôlement, la matière change et la méthode reste. Ce qui me manque, c'est la culture bancaire et réglementaire. C'est ce que je viens construire chez mc2i, en commençant par la banque digitale et les paiements, où je serai utile le plus vite."}},{"id":"m09-salaire","order":9,"title":"Salaire, questions à poser, conclusion","subtitle":"Répondre sans flotter, questionner juste, finir proprement","format":"video","workMinutes":7,"why":"Le processus mc2i place les prétentions salariales à ce type d'entretien, et tes questions finales montrent ta préparation.","voice":"Sulafat","scenes":[{"layout":"title","kicker":"Module 9","heading":"Salaire, questions, conclusion","sub":"La fin de l'échange se prépare aussi"},{"layout":"bullets","kicker":"La règle","heading":"Tu laisses venir le sujet","items":["Tu ne l'ouvres pas en premier","Tu réponds en une phrase, sans t'excuser","Pas d'autres offres ni de comparaison","Ensuite, silence"]},{"layout":"quote","kicker":"La phrase","heading":"Une seule fourchette","quote":"Je vise entre 44 et 46 k€ brut fixe.","author":"Une phrase, puis silence"},{"layout":"cards","kicker":"Les relances","heading":"Trois relances, trois réponses courtes","items":[{"t":"« C'est élevé »","d":"Quelle est votre grille pour ce poste ?"},{"t":"« Et en dessous ? »","d":"Je regarderai l'ensemble : mission, encadrement, avantages."},{"t":"Un chiffre proposé","d":"Je le note et je vous réponds sur la proposition complète."}]},{"layout":"cards","kicker":"Les avantages affichés","heading":"À regarder dans une proposition","items":[{"t":"Transports","d":"Affichés à 100 %"},{"t":"Tickets-restaurants","d":"Sur les offres mc2i"},{"t":"Mutuelle","d":"Sur les offres mc2i"},{"t":"Actionnariat salarié","d":"Capital détenu par managers et collaborateurs"},{"t":"Télétravail","d":"Possible, à préciser pour ton poste"}]},{"layout":"bullets","kicker":"Questions 1 à 3","heading":"Le produit, la roadmap, la recette","items":["RCSA : pourquoi le rôle de PO y est-il difficile ?","Banque des Territoires : arbitrer une roadmap sous contrainte","Recette : ce qui reste vrai, ce qu'on attend d'un junior"]},{"layout":"bullets","kicker":"Questions 4 à 6","heading":"Les missions, Londres, la progression","items":["Quelles missions pour un profil produit mobile, quelle durée ?","Après Londres : des missions en anglais au pôle ?","Qui progresse vite durant les deux premières années ?"]},{"layout":"flow","kicker":"Conclure","heading":"Trois temps, trente secondes","items":[{"t":"Remercier","d":"Citer un point de cet échange"},{"t":"Confirmer","d":"Banque digitale, envie d'apprendre"},{"t":"Demander","d":"Quelles sont les prochaines étapes ?"}]},{"layout":"flow","kicker":"Et après","heading":"Les prochaines étapes annoncées par mc2i","items":[{"t":"Ce soir","d":"Expériences, potentiel, missions"},{"t":"3e entretien","d":"Un membre de la Direction"},{"t":"Si tout est positif","d":"Onboarding, CV interne, mission"}]}],"takeaways":["Tu n'ouvres pas le sujet du salaire. S'il vient : 44-46 k€ brut fixe, puis silence.","Aucun autre chiffre, aucune comparaison avec d'autres offres.","Avantages affichés : transports, tickets-restaurants, mutuelle, actionnariat salarié, télétravail possible.","Deux questions à garder quoi qu'il arrive : le rôle de PO sur le RCSA, et les missions pour ton profil.","Dernière phrase : « Quelles sont les prochaines étapes ? »"],"quiz":[{"q":"L'entretien touche à sa fin et personne n'a parlé de salaire. Que fais-tu ?","choices":["Tu l'abordes, puisque le processus officiel le prévoit à ce stade.","Tu ne l'ouvres pas : tu poses tes questions et tu demandes les prochaines étapes.","Tu glisses ta fourchette dans ta conclusion, pour gagner du temps."],"answer":1,"why":"Le processus dit que le sujet sera abordé. Il ne te demande pas de l'ouvrir. Il pourra revenir avec la personne qui suit ta candidature."},{"q":"« Quelles sont vos prétentions ? »","choices":["« Je vise entre 44 et 46 k€ brut fixe. »","« Quel est votre budget pour ce poste ? »","« Entre 44 et 46, mais je peux m'adapter si besoin. »"],"answer":0,"why":"La deuxième réponse esquive, et la troisième retire de la valeur à ta fourchette dans la même phrase."},{"q":"Quelle question pose-t-on à un Directeur et Associé ?","choices":["« Quel est le chiffre d'affaires de mc2i ? »","« Comment devient-on associé chez vous ? »","« Sur un outil comme le suivi des contrôles RCSA, qu'est-ce qui rend le rôle de Product Owner difficile par rapport à un produit grand public ? »"],"answer":2,"why":"Le chiffre d'affaires est public, et le statut d'associé est un sujet à ne pas ouvrir. La bonne question part de son périmètre et de ta vraie curiosité produit."}],"drill":{"prompt":"À voix haute : réponds à « Quelles sont vos prétentions salariales ? », pose une question, puis conclus.","seconds":60,"model":"Je vise entre 44 et 46 k€ brut fixe. [silence] De mon côté, j'ai une question : sur un outil comme le suivi des contrôles RCSA, qu'est-ce qui rend le rôle de Product Owner difficile par rapport à un produit grand public ? [réponse] Merci pour cet échange, et pour ce point sur le RCSA. Cet échange renforce mon envie de rejoindre le pôle Banque Finance Assurance, en commençant par la banque digitale, et d'y apprendre la matière. Quelles sont les prochaines étapes ?"},"video":"media/m09-salaire.mp4#t=0.6","mediaMinutes":3.1},{"id":"m10-flash","order":10,"title":"Tir rapide final","subtitle":"Douze questions à voix haute, de la plus simple à la plus dure","format":"flash","workMinutes":8,"why":"À 18h, les questions arrivent sans prévenir : ce dernier passage vérifie que tes réponses sortent courtes et justes.","cards":[{"q":"Présentez-vous en trente secondes.","seconds":30,"points":["Chef de produit junior chez Orange Innovation, en appui du Product Owner, ton tuteur","Besoins pays et métier, spécifications, suivi des résultats","Le mobile comme lien direct avec la banque de détail","Ce qui te manque, dit avant qu'on te le fasse remarquer : la culture bancaire et réglementaire"]},{"q":"Quelle différence faites-vous entre MOA, AMOA et MOE ? Citez trois livrables d'un AMOA.","seconds":30,"points":["MOA : le client, qui porte le besoin","AMOA : aide à exprimer, formaliser et suivre ce besoin","MOE : conception et réalisation technique","Spécifications fonctionnelles, cahier de recette, PV de recette"]},{"q":"Pourquoi mc2i, et pas un autre cabinet ?","seconds":45,"points":["Intervention au niveau opérationnel des projets","Indépendance : pas de solution à vendre, libre de conseiller le client","Tu connais le cabinet : équipe de six, refonte du site, défendue devant la direction de mc2i","Management de proximité, sans parler de « deux ans contre cinq »"]},{"q":"Où vous voyez-vous dans cinq ans, à quel poste, dans quel secteur ?","seconds":30,"points":["Consultant senior au pôle Banque Finance Assurance","Expertise reconnue sur ton domaine","Solide sur le fonctionnel, puis pilotage de projet","Une réponse nette, sans « je ne sais pas, potentiellement »"]},{"q":"Orange, Beauty'ly, Leroy Merlin : c'est du retail et des télécoms. Que venez-vous faire en banque, et sur quel sujet précis ?","seconds":45,"points":["Banque digitale et moyens de paiement : application, enrôlement, souscription, CRM","Baromètre mc2i 2026 : l'application est devenue un prérequis","Contrainte vécue : consentement en Pologne, base adressable réduite","Tu n'as jamais travaillé en banque, et tu le dis"]},{"q":"Que savez-vous de DORA ?","seconds":45,"points":["Résilience opérationnelle numérique du secteur financier, applicable depuis le 17 janvier 2025","Cinq piliers : risques TIC, incidents, tests, prestataires tiers, partage d'informations","Dix-neuf tiers critiques désignés en novembre 2025, Orange en fait partie, sans suggérer que tu y as travaillé","Tu en connais les enjeux, tu ne l'as pas pratiqué en mission"]},{"q":"Qu'est-ce qui bouge en ce moment sur les paiements et le crédit à la consommation ?","seconds":45,"points":["CCD2 s'applique le 20 novembre 2026, le paiement fractionné entre dans le crédit réglementé","Virement instantané au tarif du virement classique, vérification du bénéficiaire depuis le 9 octobre 2025","PSR/DSP3 : accord politique, adoption formelle en cours, application pas avant 2028","Wero s'étend au paiement en ligne, sans date précise"]},{"q":"Sur la refonte de notre site, vous étiez six. Qu'avez-vous produit exactement ?","seconds":45,"points":["« Je » : l'audit stratégique, d'où viennent le diagnostic et le benchmark","Méthode : autres sites comparés par catégories, sur des critères objectifs","« Nous » : Drupal vers WordPress, 3 pages, SEO/GEO, agent IA, matrice impact × effort, roadmap à 6 mois","Défendu devant la direction de mc2i"]},{"q":"Votre reporting, c'était finalement de l'ad hoc tous les mois. Et le dashboard, qui l'utilise vraiment ?","seconds":45,"points":["Reporting mensuel, 130 destinataires, adapté chaque mois aux messages à porter","Le format statique a motivé la refonte en dashboard self-service","Trois pôles, définitions rapprochées, spécifications écrites avec les rôles et les besoins de chacun","Livré en fin d'alternance : pas de mesure d'usage dans la durée, premiers retours positifs"]},{"q":"Vos onze millions d'euros, ils reposent sur quoi, et quel était votre rôle ?","seconds":45,"points":["≈ 11 M€ de revenus modélisés, à présenter comme une modélisation","Business cases avec 5 filiales, modèles à cinq ans, données collectées auprès des pays, benchmarks","Fait en appui du Product Owner, ton tuteur","Le message : le coût de la non-action dépassait le coût de l'action"]},{"q":"Quelles sont vos prétentions salariales ?","seconds":20,"points":["Tu réponds seulement parce que la question est posée","« Je vise 44 à 46 k€ brut fixe. »","Une seule fourchette, puis silence"]},{"q":"Vous ne connaissez pas le risque. Je vous place demain sur un outil de suivi RCSA, côté deuxième ligne de défense. Que faites-vous la première semaine ?","seconds":60,"points":["Tu dis d'emblée que la matière risque est à apprendre","RCSA : les métiers évaluent leurs risques et leurs contrôles ; LoD2 : risques et conformité, qui fixent le cadre et challengent","Première semaine : rencontrer les utilisateurs, comprendre les règles, vérifier les définitions des données du reporting","Banque digitale reste ta préférence, et tu acceptes volontiers cette mission"]}]}],"cheat":{"title":"Pendant l'entretien","reminder":"Phrases courtes, « je » pour tes réalisations, « nous » pour le groupe, puis tu termines ta phrase et tu te tais.","oneLiner":"Deux ans sur un produit mobile chez Orange, entre le métier, les équipes techniques et les filiales : je veux mettre cette pratique au service de la banque digitale et des paiements, en consultant AMOA.","columns":[{"title":"Ouverture et positionnement","blocks":[{"title":"Pitch 30 secondes","style":"phrases","items":["« Chef de produit junior chez Orange Innovation, sur App Center, deux ans. »","« En appui du Product Owner, mon tuteur. »","« Besoins pays et métier, spécifications, suivi des résultats. »","« La banque de détail se joue sur ce même support : application, enrôlement, souscription, relation client. »","« Ce qui me manque : la culture bancaire et réglementaire. Je viens la construire chez mc2i. »"]},{"title":"Pourquoi la banque","style":"phrases","items":["« La banque de détail se joue maintenant sur le mobile. »","« Votre baromètre 2026 : l'application est devenue un prérequis. »","« Consentement en Pologne : base adressable réduite dans mon business case. »","« En banque, cette contrainte est partout. J'ai envie d'apprendre à concevoir avec. »"]},{"title":"Pourquoi le conseil","style":"phrases","items":["« Mettre d'accord pays, métier et technique : ce que j'ai préféré chez Orange. »","« Plusieurs projets, des méthodes éprouvées, des gens plus expérimentés. »","« Solide sur le fonctionnel, puis le pilotage de projet. »"]},{"title":"Pourquoi mc2i","style":"phrases","items":["« Le niveau opérationnel des projets : c'est là que je veux apprendre. »","« Indépendance : libre de recommander ce qui convient au client. »","« Je vous connais : équipe de six, refonte de votre site, défendue devant votre direction. »","« Management de proximité, club Banque Finance Assurance. »"]},{"title":"Mon terrain","style":"facts","items":["Banque digitale et moyens de paiement (offre mc2i)","Application, enrôlement, souscription, CRM, vie du compte, virement instantané, Wero","Référence mc2i : banque française 100 % mobile, AMOA en équipes Scrum","Taux de transformation 8,5 % contre 6,5 %, Apple Store 4,5/5 contre 3,1"]},{"title":"Si risque ou assurance","style":"phrases","items":["« J'irai volontiers. Je sais que vous recrutez sur profil. »","« Des utilisateurs à comprendre, des règles à spécifier, un reporting juste. »","« La matière, je l'apprendrai dès le départ. »","« La banque digitale est ma préférence : j'y serai utile le plus vite. »"]},{"title":"Projection","style":"phrases","items":["« Dans cinq ans : consultant senior au pôle Banque Finance Assurance, expertise reconnue sur mon domaine. »","« Ma recherche porte sur le conseil, mc2i est mon processus le plus avancé. »","Paris, mobilité internationale. Mission en anglais : oui."]},{"title":"Annoncé le 15/10 par Marion Auger","style":"list","items":["Missions voulues","Connaissance du secteur","Projection","Sous-secteur précis","Rôle exact, ce que tu as produit","« La motivation qui est saine »"]}]},{"title":"Preuves chiffrées et amorces","blocks":[{"title":"Orange : business cases","style":"facts","items":["5 filiales","Modèles à cinq ans","≈ 11 M€ de revenus modélisés","Données collectées auprès des pays, benchmarks","Contrats groupe, appliqués localement par les pays"]},{"title":"Orange : reporting","style":"facts","items":["Reporting mensuel, 130 destinataires","Refondu en dashboard web self-service","Trois pôles : App Center, pays, technique","Sources, périodes et définitions rapprochées","VBA sur classeurs entiers, migration GA4 vers Kibana"]},{"title":"Amorces Orange","style":"phrases","items":["« En appui du Product Owner, j'ai pris en charge le recueil des besoins, les spécifications et la construction du dashboard. »","« Le coût de la non-action était plus haut que le coût de l'action. »","« Avant d'afficher un indicateur, je vérifie que tout le monde parle de la même chose. »","« Chaque mois, le reporting s'adaptait aux messages à porter. Ce format statique a motivé la refonte. »","« Livré en fin d'alternance. Pas de mesure d'usage dans la durée, premiers retours positifs. »"]},{"title":"Cas mc2i (équipe de six)","style":"facts","items":["Défendu devant la direction de mc2i","Mon apport : l'audit stratégique, source du diagnostic et du benchmark","Nous : Drupal vers WordPress, 3 pages, SEO/GEO, agent IA","Nous : matrice impact × effort, roadmap 6 mois"]},{"title":"Amorce cas mc2i","style":"phrases","items":["« Mon apport propre : l'audit stratégique. »","« J'ai comparé d'autres sites, par catégories, sur des critères objectifs. »","« Ensuite, à six, nous avons priorisé par impact et par effort. »","« J'ai toute l'étude si vous souhaitez la voir. »"]},{"title":"Ponts vers la banque","style":"phrases","items":["Parcours : « Sur l'enrôlement, la matière change, la méthode reste. »","Données : « Un même indicateur, une même définition. »","CRM : « Les campagnes y sont conçues sous contrainte RGPD. »"]},{"title":"Réglementaire vécu","style":"phrases","items":["« En appui de mon Product Owner, j'ai vu ce que la DMA et le consentement changent à un produit. »","Consentement en Pologne : base adressable réduite","Rester à ce niveau : en appui"]},{"title":"Nexus Ops","style":"facts","items":["CRM sur mesure, conçu et développé seul","Avec des assistants IA, sous ma spécification et mes contrôles","Segmentation, score santé client, campagnes RGPD"]},{"title":"Autres preuves","style":"facts","items":["IA chez Orange : outil interne autorisé, pilote Claude Code en fin d'alternance","Beauty'ly : effort supérieur au revenu, retours clients non garantis, arrêt, données suivies de bout en bout","Leroy Merlin : seul au rayon le dimanche, 30+ clients par jour, ≈ 20 % du CA commandes du rayon","Anglais C2, arabe et français natifs"]}]},{"title":"Savoirs, questions, secours","blocks":[{"title":"AMOA","style":"facts","items":["MOA : le client, porte le besoin","AMOA : aide à exprimer, formaliser, suivre","MOE : conception et réalisation technique","Livrables : spécifications, plan et cahier de recette, anomalies, PV, comités","Cycle en V : chaque phase de test répond à une phase de conception","Agile : même posture, travail en itérations. User story + critères d'acceptation"]},{"title":"DORA","style":"facts","items":["Résilience opérationnelle numérique, secteur financier, 17 janvier 2025","5 piliers : risques TIC, incidents, tests, prestataires tiers, partage d'informations","Registre d'information : contrats prestataires TIC","18 nov. 2025 : 19 tiers critiques, dont Orange (pas de travail DORA chez Orange)","« Je connais les enjeux, je ne l'ai pas encore pratiqué en mission. »"]},{"title":"Paiements et crédit","style":"facts","items":["Virement instantané : même tarif que le classique depuis le 9 janv. 2025","VoP, concordance nom et IBAN : 9 oct. 2025","Wero : s'étend au paiement en ligne, pas de date précise","PSR/DSP3 : accord politique, adoption formelle en cours, application pas avant 2028","CCD2 : 20 novembre 2026, le paiement fractionné entre dans le crédit réglementé","FIDA : bloquée, un retrait est évoqué"]},{"title":"Faits mc2i","style":"facts","items":["200 M€ CA 2025, +10 % organique, ~1700 personnes, 36 ans","218 managers associés, 100 % managers et collaborateurs au capital","Bienveillance, Engagement, Curiosité, Liberté","Alliance : Tasmane, Ogures, Inditto","1 manager pour 5 consultants, recrutement sur profil","Pôle : Lorenzo Bertola, Julien Robustelli","Baromètre 2026 : 62 % mono-bancarisés, 55 % veulent un hébergement européen"]},{"title":"Frédéric Bertrais","style":"facts","items":["Directeur & Associé depuis déc. 2023, plus de 15 ans chez mc2i","Outil de notation risque de crédit corporate (PO, agilité)","Outil de suivi contrôles et plans d'actions (RCSA / LoD2)","DORA en contexte bancaire","Caisse des Dépôts : 5 équipes agiles ; PO prêts aux collectivités","Londres 2014-2018 : SI Trésorerie Total UK","Avant mc2i : BNP Paribas, Cetelem. Centrale Lille","PSPO I, PSM II, PRINCE2. Tribune sur les outils de recette (2012)","Attendu : expériences creusées, potentiel, missions"]},{"title":"Sigles risque, pour comprendre","style":"list","items":["RCSA : auto-évaluation des risques et contrôles par les métiers","LoD1 : les métiers. LoD2 : risques et conformité. LoD3 : audit interne"]},{"title":"Questions à poser","style":"phrases","items":["« Sur un outil comme le suivi RCSA, qu'est-ce qui rend le rôle de Product Owner difficile par rapport à un produit grand public ? »","« Quelles missions confiez-vous à un junior au pôle Banque Finance Assurance ? »","« Quelle est la durée habituelle d'une mission ? »","« Quel délai entre l'arrivée et la première mission ? »","« Quelle est la suite du processus ? »"]},{"title":"Salaire, seulement si abordé","style":"phrases","items":["« Je vise 44 à 46 k€ brut fixe. »","Ensuite, silence."]},{"title":"Si blocage","style":"phrases","items":["« Je prends une seconde pour structurer ma réponse. »","« Pour être sûr de bien répondre : vous parlez de… ? »","« Je ne l'ai pas encore pratiqué. Voici comment je l'aborderais. »","« Je préfère ne pas vous donner un chiffre approximatif. »","« Je ne connais pas ce métier. Ce qui me parle, c'est… »"]},{"title":"À ne pas dire","style":"warn","items":["« J'ai une expérience bancaire »","« J'ai découvert ce domaine »","« De A à Z » sur Orange","« Deux ans contre cinq ans »","Orange Bank comme référence","Cas mc2i sans « équipe de six »","Jargon Bâle, CRR/CRD non maîtrisé"]},{"title":"Tics à éviter","style":"warn","items":["« du coup », « genre », « on va dire »","« comment dire », « globalement », « et tout »","« tu sais », « des trucs un peu comme ça »","« Je ne sais pas si… » : termine et tais-toi"]}]}]}};
window.PREPA.cheat2={"oneLiner":"Deux ans de produit mobile chez Orange, pour la banque digitale en AMOA.","tabs":[{"id":"debut","label":"Début","blocks":[{"title":"Pitch 30 secondes","kind":"say","lines":["« Chef de produit junior chez Orange Innovation, sur App Center, deux ans. »","« En appui du Product Owner, mon tuteur. »","« J'ai recueilli les besoins, écrit les spécifications, suivi les résultats. »","« La banque de détail se joue sur ce support : l'application mobile. »","« Il me manque la culture bancaire. Je viens la construire chez mc2i. »"]},{"title":"Rôle exact chez Orange","kind":"fact","lines":["Chef de produit junior, Orange Innovation","App Center, produit mobile, deux ans","En appui du Product Owner, mon tuteur","Besoins pays et métier, spécifications, suivi"]},{"title":"Réflexes","kind":"fact","lines":["« Je » pour moi, « nous » pour le groupe","Phrase finie, je me tais","Paris, mobilité internationale","Mission en anglais : oui (anglais C2)"]}]},{"id":"pourquoi","label":"Pourquoi","blocks":[{"title":"Pourquoi la banque","kind":"say","lines":["« La banque de détail se joue maintenant sur le mobile. »","« Votre baromètre 2026 : l'application est devenue un prérequis. »","« Consentement en Pologne : base adressable réduite dans mon business case. »","« Cette contrainte est partout en banque. Je veux apprendre à concevoir avec. »"]},{"title":"Pourquoi le conseil","kind":"say","lines":["« Mettre d'accord pays, métier et technique : ce que j'ai préféré chez Orange. »","« Plusieurs projets, des méthodes éprouvées, des gens plus expérimentés. »","« Solide sur le fonctionnel, puis le pilotage de projet. »"]},{"title":"Pourquoi mc2i","kind":"say","lines":["« Le niveau opérationnel des projets : c'est là que je veux apprendre. »","« Indépendance : vous recommandez ce qui convient au client. »","« Refonte de votre site en équipe de six, défendue devant votre direction. »","« Management de proximité, club Banque Finance Assurance. »"]},{"title":"Risque, assurance, et dans cinq ans","kind":"say","lines":["« Risque ou assurance : j'irai volontiers, vous recrutez sur profil. »","« Mêmes bases : des utilisateurs, des règles à spécifier, un reporting juste. »","« La matière, je l'apprendrai dès le départ. »","« La banque digitale reste une préférence, pas une condition. »","« Dans cinq ans : consultant senior en banque-assurance, expertise reconnue. »"]}]},{"id":"preuves","label":"Preuves","blocks":[{"title":"Orange : business cases et réglementaire","kind":"fact","lines":["5 filiales, modèles à cinq ans","≈ 11 M€ de revenus modélisés","Données collectées auprès des pays, benchmarks","Pologne : consentement, base adressable réduite","En appui du Product Owner : impact DMA et consentement"]},{"title":"Orange : du reporting au dashboard","kind":"fact","lines":["Reporting mensuel, 130 destinataires","Refondu en dashboard web self-service","Sources, périodes, définitions rapprochées","Limite : livré fin d'alternance, pas de mesure d'usage","Premiers retours positifs"]},{"title":"Cas mc2i : je et nous","kind":"fact","lines":["Équipe de six, défendu devant la direction de mc2i","Je : audit stratégique, d'où diagnostic et benchmark","Nous : Drupal vers WordPress, 3 pages, SEO/GEO, agent IA","Nous : matrice impact × effort, roadmap 6 mois","« J'ai toute l'étude si vous souhaitez la voir. »"]},{"title":"Nexus Ops","kind":"fact","lines":["CRM sur mesure, conçu et développé seul","Assistants IA, sous ma spécification et mes contrôles","Segmentation, score santé client, campagnes RGPD","Pont banque : CRM et vie du compte"]}]},{"id":"banque","label":"Banque","blocks":[{"title":"Mon terrain","kind":"fact","lines":["Banque digitale et moyens de paiement","Application, enrôlement, souscription, CRM, vie du compte","Virement instantané, Wero","Réf. mc2i : banque 100 % mobile, AMOA en équipes Scrum","« Sur l'enrôlement, la matière change, la méthode reste. »"]},{"title":"DORA","kind":"fact","lines":["Résilience numérique de la finance, depuis le 17 janv. 2025","5 piliers : risques, incidents, tests, tiers, partage","Tiers critiques : 19 dont Orange. Moi : pas pratiqué"]},{"title":"Paiements","kind":"fact","lines":["Virement instantané : tarif du classique, janv. 2025","Wero : s'étend au paiement en ligne, pas de date précise","DSP3 : pas avant 2028. CCD2 : dès le 20 nov. 2026"]},{"title":"Faits mc2i","kind":"fact","lines":["200 M€ CA 2025, +10 % organique, ~1700 personnes, 36 ans","Capital 100 % interne, 1 manager pour 5 consultants","Bienveillance, Engagement, Curiosité, Liberté","Pôle : Lorenzo Bertola, Julien Robustelli","Baromètre 2026 : 62 % mono-bancarisés"]}]},{"id":"defs","label":"Défs","groups":[{"title":"Agile","items":[{"t":"Agile","d":"Avancer par petites étapes et ajuster selon les retours."},{"t":"Scrum","d":"Une façon d'organiser l'Agile : cycles courts, rôles clairs."},{"t":"Sprint","d":"Un cycle court de travail, souvent deux semaines."},{"t":"Backlog","d":"La liste priorisée de tout ce qu'il reste à faire."},{"t":"User story","d":"Un besoin écrit du point de vue de l'utilisateur."},{"t":"Product Owner","d":"Décide quoi construire d'abord, pour apporter le plus de valeur."},{"t":"Scrum Master","d":"Aide l'équipe à bien appliquer Scrum et lève les blocages."},{"t":"Daily","d":"Point d'équipe rapide chaque jour : avancement et blocages."},{"t":"Rétrospective","d":"En fin de cycle, l'équipe voit quoi améliorer."},{"t":"SAFe","d":"L'Agile à grande échelle, pour coordonner plusieurs équipes."}]},{"title":"Projet","items":[{"t":"MOA","d":"Le client : celui qui porte le besoin."},{"t":"MOE","d":"Ceux qui conçoivent et construisent la solution technique."},{"t":"AMOA","d":"Aide le client à exprimer, écrire et suivre son besoin."},{"t":"Business analyst","d":"Transforme le besoin métier en exigences claires."},{"t":"Cycle en V","d":"On conçoit d'abord, on construit, puis chaque étape est testée."},{"t":"Cadrage","d":"Au départ : objectif, périmètre, délais, budget, qui fait quoi."},{"t":"Spécifications","d":"Ce que l'outil doit faire, écrit noir sur blanc."},{"t":"Recette","d":"Le client vérifie que tout marche avant la mise en service."},{"t":"Mise en production","d":"Le moment où l'outil arrive chez les vrais utilisateurs."},{"t":"Run","d":"Faire tourner l'outil au quotidien après sa livraison."},{"t":"Conduite du changement","d":"Préparer les gens à adopter la nouvelle façon de travailler."},{"t":"KPI","d":"Un chiffre suivi pour savoir si l'objectif est atteint."}]},{"title":"Banque et réglementation","items":[{"t":"DORA","d":"Règle européenne : la finance doit résister aux pannes et aux cyberattaques."},{"t":"TIC","d":"Les technologies de l'information : informatique, réseaux, données."},{"t":"Prestataire critique","d":"Fournisseur informatique clé, surveillé par l'Europe. Orange en fait partie."},{"t":"TLPT","d":"Attaque simulée et réaliste pour tester la défense d'une banque."},{"t":"RCSA","d":"Chaque métier évalue lui-même ses risques et ses contrôles."},{"t":"Lignes de défense LoD1 LoD2 LoD3","d":"LoD1 métiers, LoD2 risques et conformité, LoD3 audit interne."},{"t":"Notation de crédit","d":"Une note qui mesure le risque qu'une entreprise ne rembourse pas."},{"t":"Virement instantané","d":"Un virement immédiat, au même tarif qu'un virement classique."},{"t":"Wero","d":"Solution européenne de paiement mobile, qui s'étend aux achats en ligne."},{"t":"DSP3 et PSR","d":"Futures règles européennes des paiements, pas appliquées avant 2028."},{"t":"CCD2 et paiement fractionné","d":"Crédit conso : payer en plusieurs fois sera encadré dès le 20/11/2026."},{"t":"KYC","d":"Vérifier qui est vraiment le client."},{"t":"AML","d":"La lutte contre le blanchiment d'argent."},{"t":"Bâle 3 et CRR3","d":"Règles imposant aux banques assez de capital pour encaisser les pertes."},{"t":"AI Act","d":"Loi européenne sur l'IA. Noter un emprunteur : haut risque, à venir."},{"t":"RGPD","d":"Règles européennes sur les données personnelles et le consentement."},{"t":"DMA","d":"Règle européenne qui limite le pouvoir des très grandes plateformes."},{"t":"Solvabilité 2","d":"Solidité financière des assureurs. Version révisée applicable le 30 janvier 2027."}]}]},{"id":"lui","label":"Bertrais","blocks":[{"title":"Frédéric Bertrais aujourd'hui","kind":"fact","lines":["Directeur & Associé depuis déc. 2023","Plus de 15 ans chez mc2i","Encadre managers et senior managers"]},{"title":"Projets affichés","kind":"fact","lines":["Notation risque de crédit corporate (Product Owner, agilité)","Suivi contrôles et plans d'actions (RCSA / LoD2)","Résilience opérationnelle bancaire (DORA)","Caisse des Dépôts : 5 équipes agiles, PO prêts collectivités","Londres 2014-2018 : SI Trésorerie Total UK"]},{"title":"Parcours","kind":"fact","lines":["Avant mc2i : BNP Paribas, Cetelem","Centrale Lille, informatique","PSPO I, PSM II, PRINCE2","Tribune sur les outils de recette (2012)"]},{"title":"Ce qui est évalué","kind":"fact","lines":["Expériences creusées","Comportement, technique, potentiel","Échange sur les missions"]}]},{"id":"fin","label":"Fin","blocks":[{"title":"Mes 5 questions","kind":"say","lines":["« Sur un outil RCSA, qu'est-ce qui rend le rôle de Product Owner difficile ? »","« Quelles missions confiez-vous à un junior au pôle Banque Finance Assurance ? »","« Quelle est la durée habituelle d'une mission ? »","« Quel délai entre l'arrivée et la première mission ? »","« Quelle est la suite du processus ? »"]},{"title":"Salaire : si on le demande, puis silence","kind":"say","lines":["« Je vise 44 à 46 k€ brut fixe. »"]},{"title":"Pour conclure","kind":"say","lines":["« Cet échange confirme mon envie de rejoindre mc2i. »"]}]},{"id":"secours","label":"Secours","blocks":[{"title":"Si je bloque","kind":"say","lines":["« Je prends une seconde pour structurer ma réponse. »","« Pour être sûr de bien répondre : vous parlez de… ? »","« Je ne l'ai pas encore pratiqué. Voici comment je l'aborderais. »","« Je préfère ne pas vous donner un chiffre approximatif. »","« Je ne connais pas ce métier. Ce qui me parle, c'est… »"]},{"title":"Tics à éviter","kind":"warn","lines":["« du coup », « genre », « on va dire »","« comment dire », « globalement », « et tout »","« tu sais », « des trucs un peu comme ça »","« Je ne sais pas si… » : termine et tais-toi"]},{"title":"À ne pas dire","kind":"warn","lines":["« J'ai une expérience bancaire »","« J'ai découvert ce domaine »","« Deux ans contre cinq ans »","Orange Bank comme référence","Jargon Bâle, CRR/CRD non maîtrisé"]},{"title":"Erreurs sur mes preuves","kind":"warn","lines":["« De A à Z » sur Orange : dire « en appui »","≈ 11 M€ sans « modélisés »","Cas mc2i sans « équipe de six »","Dire que toute l'équipe voit le dashboard chaque jour","Parler salaire le premier"]}]}]};
